'use client'

import dynamic from 'next/dynamic'
import { useCallback } from 'react'
import { useRouter, useSearchParams } from 'next/navigation'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { toast } from 'sonner'
import { Skeleton } from '@/components/ui/skeleton'
import { AppointmentDrawer } from '@/components/appointments/AppointmentDrawer'
import type { CalendarBooking } from '@/components/calendar/CalendarView'
import { useCalendarDrawer } from '@/hooks/calendar/use-calendar-drawer'
import { PageShell } from '@/components/shared/PageShell'

// Must be ssr:false — FullCalendar uses browser globals
const CalendarView = dynamic(
  () =>
    import('@/components/calendar/CalendarView').then((mod) => mod.CalendarView),
  {
    ssr: false,
    loading: () => (
      <div className="flex-1 p-4 space-y-3">
        <div className="flex items-center gap-3">
          <Skeleton className="h-9 w-32 rounded-lg" />
          <Skeleton className="h-9 w-24 rounded-lg" />
          <Skeleton className="h-9 w-24 rounded-lg" />
          <div className="ml-auto flex gap-2">
            <Skeleton className="h-9 w-9 rounded-lg" />
            <Skeleton className="h-9 w-20 rounded-lg" />
            <Skeleton className="h-9 w-9 rounded-lg" />
          </div>
        </div>
        <Skeleton className="h-[60vh] w-full rounded-xl" />
      </div>
    ),
  }
)

// ── C7: URL search param helpers ────────────────────────────────────────────
function parseIds(value: string | null): string[] {
  if (!value) return []
  return value.split(',').filter(Boolean)
}

function serializeIds(ids: string[]): string {
  return ids.join(',')
}

export function CalendarPageClient() {
  const router = useRouter()
  const searchParams = useSearchParams()
  const queryClient = useQueryClient()

  // ── C7: Lift filter state into URL ─────────────────────────────────────
  const filterArtistIds = parseIds(searchParams.get('artists'))
  const filterStatuses = parseIds(searchParams.get('statuses'))
  const filterServiceIds = parseIds(searchParams.get('services'))

  function updateFilters(updates: {
    artists?: string[]
    statuses?: string[]
    services?: string[]
  }) {
    const next = new URLSearchParams(searchParams.toString())
    if (updates.artists !== undefined) {
      if (updates.artists.length > 0) {
        next.set('artists', serializeIds(updates.artists))
      } else {
        next.delete('artists')
      }
    }
    if (updates.statuses !== undefined) {
      if (updates.statuses.length > 0) {
        next.set('statuses', serializeIds(updates.statuses))
      } else {
        next.delete('statuses')
      }
    }
    if (updates.services !== undefined) {
      if (updates.services.length > 0) {
        next.set('services', serializeIds(updates.services))
      } else {
        next.delete('services')
      }
    }
    router.replace(`?${next.toString()}`, { scroll: false })
  }

  // ── Drawer state ────────────────────────────────────────────────────────
  const {
    drawerOpen,
    setDrawerOpen,
    editingId,
    defaultStart,
    defaultEnd,
    openNew,
    openEdit,
  } = useCalendarDrawer()

  const {
    data,
    isLoading,
    error,
    refetch,
  } = useQuery<{ data: CalendarBooking[]; count: number }>({
    queryKey: ['bookings', 'calendar'],
    queryFn: async () => {
      const res = await fetch('/api/bookings?per_page=500')
      if (!res.ok) throw new Error('Failed to fetch bookings')
      return res.json() as Promise<{ data: CalendarBooking[]; count: number }>
    },
  })

  const rescheduleMutation = useMutation({
    mutationFn: async ({
      id,
      newStart,
      newEnd,
    }: {
      id: string
      newStart: Date
      newEnd: Date
    }) => {
      const durationMs = newEnd.getTime() - newStart.getTime()
      const duration_min = Math.round(durationMs / 60000)
      const res = await fetch(`/api/bookings/${id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          scheduled_at: newStart.toISOString(),
          duration_min,
        }),
      })
      if (!res.ok) {
        const err = await res.json() as { error?: string }
        throw new Error(err.error ?? 'Reschedule failed')
      }
      return res.json()
    },
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: ['bookings'] })
    },
  })

  const handleReschedule = useCallback(
    async (id: string, newStart: Date, newEnd: Date) => {
      await rescheduleMutation.mutateAsync({ id, newStart, newEnd })
    },
    [rescheduleMutation]
  )

  const bookings = data?.data ?? []
  const totalBookings = data?.count ?? 0

  return (
    <PageShell fullHeight>
      <CalendarView
        bookings={bookings}
        isLoading={isLoading}
        error={error ? (error instanceof Error ? error.message : 'Unknown error') : null}
        totalBookings={totalBookings}
        filterArtistIds={filterArtistIds}
        filterStatuses={filterStatuses}
        filterServiceIds={filterServiceIds}
        onArtistFilterChange={(ids) => updateFilters({ artists: ids })}
        onStatusFilterChange={(statuses) => updateFilters({ statuses })}
        onServiceFilterChange={(ids) => updateFilters({ services: ids })}
        onNewAppointment={openNew}
        onEditAppointment={openEdit}
        onReschedule={handleReschedule}
        onRetry={() => {
          void refetch()
        }}
      />

      <AppointmentDrawer
        open={drawerOpen}
        onOpenChange={setDrawerOpen}
        editingId={editingId}
        {...(defaultStart !== undefined ? { defaultStart } : {})}
        {...(defaultEnd !== undefined ? { defaultEnd } : {})}
        onSuccess={() => {
          setDrawerOpen(false)
          void queryClient.invalidateQueries({ queryKey: ['bookings'] })
          toast.success(editingId ? 'Appointment updated' : 'Appointment created')
        }}
      />
    </PageShell>
  )
}

'use client'

import { useRouter } from 'next/navigation'
import type { EventApi } from '@fullcalendar/core'
import { Link2 } from 'lucide-react'
import { cn } from '@/lib/utils'
import type { Database } from '@/lib/supabase/types'

type BookingStatus = Database['public']['Tables']['bookings']['Row']['status']

const STATUS_DOT_CLASSES: Partial<Record<BookingStatus, string>> = {
  in_progress: 'bg-[var(--color-status-in-progress)] animate-pulse',
  completed: 'bg-[var(--color-status-completed)]',
  cancelled: 'bg-[var(--color-status-cancelled)]',
  no_show: 'bg-[var(--color-status-no-show)]',
}

interface AppointmentCardProps {
  event: EventApi
}

export function AppointmentCard({ event }: AppointmentCardProps) {
  const router = useRouter()
  const status = event.extendedProps.status as BookingStatus
  const projectId = event.extendedProps.projectId as string | null | undefined
  const sessionNumber = event.extendedProps.sessionNumber as number | null | undefined
  const projectName = event.extendedProps.projectName as string | null | undefined
  const depositCents = event.extendedProps.depositCents as number
  const depositPaid = event.extendedProps.depositPaid as boolean

  const startTime = event.start
    ? event.start.toLocaleTimeString('en-US', {
        hour: 'numeric',
        minute: '2-digit',
        hour12: true,
      })
    : ''

  const dotClass = STATUS_DOT_CLASSES[status]
  const isCancelled = status === 'cancelled'

  // Deposit dot: only shown when deposit is required (cents > 0)
  const showDepositDot = depositCents > 0

  return (
    <div className="relative flex h-full flex-col overflow-hidden px-1.5 py-0.5">
      <div className="flex items-center justify-between gap-1">
        <span
          className={cn(
            'text-[11px] font-medium truncate',
            isCancelled && 'line-through opacity-60'
          )}
        >
          {event.title}
        </span>
        <span className="text-[11px] tabular-nums shrink-0 opacity-70">{startTime}</span>
      </div>
      {event.extendedProps.serviceName && (
        <span className="text-[10px] opacity-60 truncate">
          {event.extendedProps.serviceName}
        </span>
      )}

      {/* Status dot — shifts left when project icon present */}
      {dotClass && (
        <span
          aria-hidden="true"
          className={cn(
            'absolute bottom-1 right-1 h-1.5 w-1.5 rounded-full',
            dotClass,
            projectId && 'right-4'
          )}
        />
      )}

      {/* Deposit status dot — top-right corner */}
      {showDepositDot && (
        <span
          role="img"
          title={depositPaid ? 'Deposit paid' : 'Deposit pending'}
          aria-label={depositPaid ? 'Deposit paid' : 'Deposit pending'}
          className={cn('deposit-dot', depositPaid ? 'paid' : 'unpaid')}
        />
      )}

      {/* Project chain icon — bottom-right */}
      {projectId && (
        <button
          type="button"
          title={
            projectName
              ? `Part of project: ${projectName}${sessionNumber != null ? ` · Session ${sessionNumber}` : ''}`
              : 'View project'
          }
          aria-label={
            projectName
              ? `Part of project: ${projectName}${sessionNumber != null ? ` · Session ${sessionNumber}` : ''}`
              : 'View project'
          }
          onClick={(e) => {
            e.stopPropagation()
            router.push(`/projects/${projectId}`)
          }}
          className="project-icon"
        >
          <Link2 className="h-2.5 w-2.5" />
        </button>
      )}
    </div>
  )
}

