**Phase 1: Data Layer**

Starting with the two new API routes that fix the per_page cap and provide blocked-slot aggregation.

## `app/api/bookings/calendar/route.ts`

```typescript
import { createServerClient } from '@supabase/ssr'
import { cookies } from 'next/headers'
import { NextRequest, NextResponse } from 'next/server'
import { z } from 'zod'
import { authedRatelimit, requireFeatureRpc } from '@/lib/rate-limit'
import { createClient } from '@/lib/supabase/server'

const QuerySchema = z.object({
  from: z.string().datetime(),
  to: z.string().datetime(),
  artist_ids: z.string().optional(),
  statuses: z.string().optional(),
})

export async function GET(req: NextRequest) {
  try {
    const url = new URL(req.url)
    const parsed = QuerySchema.safeParse({
      from: url.searchParams.get('from'),
      to: url.searchParams.get('to'),
      artist_ids: url.searchParams.get('artist_ids'),
      statuses: url.searchParams.get('statuses'),
    })

    if (!parsed.success) {
      return NextResponse.json({ error: 'Invalid query params' }, { status: 400 })
    }

    const { from, to, artist_ids, statuses } = parsed.data
    const supabase = await createClient()

    // Rate limit
    const limited = await authedRatelimit()
    if (!limited.success) return NextResponse.json({ error: 'Rate limited' }, { status: 429 })

    // Get studio from auth
    const {
      data: { session },
    } = await supabase.auth.getSession()
    if (!session) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

    const {
      data: profile,
      error: profileError,
    } = await supabase
      .from('team_members')
      .select('studio_id')
      .eq('user_id', session.user.id)
      .single()

    if (profileError || !profile) {
      return NextResponse.json({ error: 'Studio not found' }, { status: 403 })
    }

    // Check feature gate
    await requireFeatureRpc(supabase, profile.studio_id, 'calendar')

    // Build query
    let query = supabase
      .from('bookings')
      .select(
        `
        id, studio_id, client_id, artist_id, service_id, scheduled_at, duration_min,
        status, notes, created_at, updated_at, deposit_cents, deposit_paid,
        client:clients(id, name, email, phone),
        artist:artists(id, display_name, color_index),
        service:services(id, name, color),
        booking_participants(id, participant_type)
      `
      )
      .eq('studio_id', profile.studio_id)
      .gte('scheduled_at', from)
      .lt('scheduled_at', to)
      .order('scheduled_at', { ascending: true })
      .limit(2000)

    if (artist_ids) {
      const ids = artist_ids.split(',').filter(Boolean)
      query = query.in('artist_id', ids)
    }

    if (statuses) {
      const statusList = statuses.split(',').filter(Boolean)
      query = query.in('status', statusList)
    }

    const { data, error, count } = await query

    if (error) throw error

    return NextResponse.json({
      data: data || [],
      count: count || 0,
    })
  } catch (err) {
    console.error('Calendar bookings fetch:', err)
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}
```

## `app/api/bookings/calendar/blocked-slots/route.ts`

```typescript
import { createServerClient } from '@supabase/ssr'
import { cookies } from 'next/headers'
import { NextRequest, NextResponse } from 'next/server'
import { z } from 'zod'
import { authedRatelimit } from '@/lib/rate-limit'
import { createClient } from '@/lib/supabase/server'

const QuerySchema = z.object({
  from: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
  to: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
})

export async function GET(req: NextRequest) {
  try {
    const url = new URL(req.url)
    const parsed = QuerySchema.safeParse({
      from: url.searchParams.get('from'),
      to: url.searchParams.get('to'),
    })

    if (!parsed.success) {
      return NextResponse.json({ error: 'Invalid query params' }, { status: 400 })
    }

    const { from, to } = parsed.data
    const supabase = await createClient()

    // Rate limit
    const limited = await authedRatelimit()
    if (!limited.success) return NextResponse.json({ error: 'Rate limited' }, { status: 429 })

    // Get studio
    const {
      data: { session },
    } = await supabase.auth.getSession()
    if (!session) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

    const {
      data: profile,
      error: profileError,
    } = await supabase
      .from('team_members')
      .select('studio_id')
      .eq('user_id', session.user.id)
      .single()

    if (profileError || !profile) {
      return NextResponse.json({ error: 'Studio not found' }, { status: 403 })
    }

    // Fetch time_off (approved only)
    const { data: timeOff, error: timeOffError } = await supabase
      .from('artist_time_off')
      .select('id, artist_id, start_date, end_date')
      .eq('studio_id', profile.studio_id)
      .eq('status', 'approved')
      .gte('end_date', from)
      .lte('start_date', to)

    if (timeOffError) throw timeOffError

    // Fetch blocked dates
    const { data: blockedDates, error: blockedError } = await supabase
      .from('artist_blocked_dates')
      .select('id, artist_id, date, reason')
      .eq('studio_id', profile.studio_id)
      .gte('date', from)
      .lte('date', to)

    if (blockedError) throw blockedError

    // Aggregate by artist
    const byArtist: Record<string, any[]> = {}

    for (const slot of timeOff || []) {
      if (!byArtist[slot.artist_id]) byArtist[slot.artist_id] = []
      byArtist[slot.artist_id].push({
        type: 'time_off',
        start: slot.start_date,
        end: slot.end_date,
        reason: 'Time off',
      })
    }

    for (const slot of blockedDates || []) {
      if (!byArtist[slot.artist_id]) byArtist[slot.artist_id] = []
      byArtist[slot.artist_id].push({
        type: 'blocked_date',
        date: slot.date,
        reason: slot.reason || 'Not available',
      })
    }

    return NextResponse.json({
      data: Object.entries(byArtist).map(([artist_id, blocked]) => ({
        artist_id,
        blocked,
      })),
    })
  } catch (err) {
    console.error('Blocked slots fetch:', err)
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}
```

## `CalendarPageClient.tsx` — Key Changes

Replace the `useQuery` fetch:

```typescript
const [rangeStart, setRangeStart] = useState<string>(() => {
  const today = new Date()
  today.setHours(0, 0, 0, 0)
  return today.toISOString()
})
const [rangeEnd, setRangeEnd] = useState<string>(() => {
  const tomorrow = new Date()
  tomorrow.setDate(tomorrow.getDate() + 1)
  tomorrow.setHours(0, 0, 0, 0)
  return tomorrow.toISOString()
})

const { data, isLoading, error, refetch } = useQuery<{
  data: CalendarBooking[]
  count: number
}>({
  queryKey: ['bookings', 'calendar', rangeStart, rangeEnd],
  queryFn: async () => {
    const params = new URLSearchParams()
    params.set('from', rangeStart)
    params.set('to', rangeEnd)
    if (filterArtistIds.length > 0) params.set('artist_ids', filterArtistIds.join(','))
    if (filterStatuses.length > 0) params.set('statuses', filterStatuses.join(','))

    const res = await fetch(`/api/bookings/calendar?${params.toString()}`)
    if (!res.ok) throw new Error('Failed to fetch bookings')
    return res.json() as Promise<{ data: CalendarBooking[]; count: number }>
  },
})
```

Pass to `CalendarView`:

```typescript
<CalendarView
  bookings={bookings}
  isLoading={isLoading}
  error={error ? (error instanceof Error ? error.message : 'Unknown error') : null}
  totalBookings={totalBookings}
  rangeStart={rangeStart}
  rangeEnd={rangeEnd}
  onViewDatesChange={(start, end) => {
    setRangeStart(start.toISOString())
    setRangeEnd(end.toISOString())
  }}
  // ... rest of props
/>
```

These three changes fix the per_page cap and enable date-range filtering. The AppointmentDrawer swap comes in Phase 3. Ready for Phase 2 (toolbar cleanup) next.

