import { NextRequest, NextResponse } from 'next/server'
import { z } from 'zod'
import { authedRatelimit } from '@/lib/rate-limit'
import { createClient } from '@/lib/supabase/server'

const QuerySchema = z.object({
  from: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
  to: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
})

interface BlockedSlot {
  type: 'time_off' | 'blocked_date'
  start?: string
  end?: string
  date?: string
  reason: string
}

interface BlockedSlotsResponse {
  data: Array<{
    artist_id: string
    blocked: BlockedSlot[]
  }>
}

export async function GET(req: NextRequest): Promise<NextResponse<BlockedSlotsResponse | { error: string }>> {
  try {
    const url = new URL(req.url)
    const parsed = QuerySchema.safeParse({
      from: url.searchParams.get('from'),
      to: url.searchParams.get('to'),
    })

    if (!parsed.success) {
      return NextResponse.json({ error: 'Invalid query params' }, { status: 400 })
    }

    const { from, to } = parsed.data
    const supabase = await createClient()

    // Get IP for rate limiting
    const ip = req.headers.get('x-forwarded-for') || req.headers.get('x-real-ip') || 'unknown'

    // Rate limit
    const limited = await authedRatelimit.limit(ip)
    if (!limited.success) return NextResponse.json({ error: 'Rate limited' }, { status: 429 })

    // Get studio
    const {
      data: { session },
    } = await supabase.auth.getSession()
    if (!session) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

    const { data: profile, error: profileError } = await supabase
      .from('team_members')
      .select('studio_id')
      .eq('user_id', session.user.id)
      .single()

    const studio_id = (profile as any)?.studio_id
    if (profileError || !studio_id) {
      return NextResponse.json({ error: 'Studio not found' }, { status: 403 })
    }

    // Fetch time_off (approved only)
    const { data: timeOff, error: timeOffError } = await supabase
      .from('artist_time_off')
      .select('id, artist_id, start_at, end_at')
      .eq('studio_id', studio_id)
      .eq('status', 'approved')
      .gte('end_at', from)
      .lte('start_at', to)

    if (timeOffError) throw timeOffError

    // Fetch blocked dates
    const { data: blockedDates, error: blockedError } = await supabase
      .from('artist_blocked_dates')
      .select('id, artist_id, blocked_date, reason')
      .eq('studio_id', studio_id)
      .gte('blocked_date', from)
      .lte('blocked_date', to)

    if (blockedError) throw blockedError

    // Aggregate by artist
    const byArtist: Record<string, BlockedSlot[]> = {}

    for (const slot of timeOff || []) {
      if (!byArtist[slot.artist_id]) byArtist[slot.artist_id] = []
      byArtist[slot.artist_id].push({
        type: 'time_off',
        start: slot.start_at,
        end: slot.end_at,
        reason: 'Time off',
      })
    }

    for (const slot of blockedDates || []) {
      if (!byArtist[slot.artist_id]) byArtist[slot.artist_id] = []
      byArtist[slot.artist_id].push({
        type: 'blocked_date',
        date: slot.blocked_date,
        reason: slot.reason || 'Not available',
      })
    }

    const result: BlockedSlotsResponse = {
      data: Object.entries(byArtist).map(([artist_id, blocked]) => ({
        artist_id,
        blocked,
      })),
    }

    return NextResponse.json(result)
  } catch (err) {
    console.error('Blocked slots fetch:', err)
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

