.artist-event-7 { border-left-color: var(--color-artist-7); background: var(--color-artist-7-surface); color: var(--color-artist-7); }
.artist-event-8 { border-left-color: var(--color-artist-8); background: var(--color-artist-8-surface); color: var(--color-artist-8); }
