'use client'

import { useState } from 'react'
import { useForm } from 'react-hook-form'
import { zodResolver } from '@hookform/resolvers/zod'
import { z } from 'zod'
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import { toast } from 'sonner'
import { Calendar, Clock } from 'lucide-react'
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
} from '@/components/ui/sheet'
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from '@/components/ui/form'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Textarea } from '@/components/ui/textarea'
import { Switch } from '@/components/ui/switch'
import { Skeleton } from '@/components/ui/skeleton'
import { ClientFinder } from '@/components/booking/ClientFinder'
import { DayPicker } from '@/components/ui/day-picker'
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover'
import { cn, formatCurrency } from '@/lib/utils'
import { logger } from '@/lib/logger'

const BookingSchema = z.object({
  service_id: z.string().uuid('Service is required'),
  artist_id: z.string().uuid('Artist is required'),
  scheduled_at: z.string().datetime('Invalid date/time'),
  duration_min: z.number().int().min(15, 'Minimum 15 minutes').max(480, 'Maximum 480 minutes'),
  client_id: z.string().uuid().optional(),
  notes: z.string().max(2000).optional(),
  send_deposit_link: z.boolean().default(false),
})

type BookingFormData = z.infer<typeof BookingSchema>

interface Service {
  id: string
  name: string
  duration_min: number
  base_price_cents: number
  deposit_cents: number
}

interface Artist {
  id: string
  display_name: string
  avatar_url: string | null
}

interface SmartBookingSheetProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  defaultStart?: Date
  defaultEnd?: Date
  defaultArtistId?: string
  editingId?: string | null
  onSuccess: (bookingId: string) => void
}

export function SmartBookingSheet({
  open,
  onOpenChange,
  defaultStart,
  defaultEnd,
  defaultArtistId,
  onSuccess,
}: SmartBookingSheetProps) {
  const queryClient = useQueryClient()
  const [selectedDate, setSelectedDate] = useState<Date | undefined>(defaultStart)
  const [selectedServiceId, setSelectedServiceId] = useState<string | null>(null)
  const [calendarOpen, setCalendarOpen] = useState(false)

  const form = useForm<BookingFormData>({
    resolver: zodResolver(BookingSchema),
    defaultValues: {
      service_id: '',
      artist_id: defaultArtistId ?? '',
      duration_min: 60,
      notes: '',
      send_deposit_link: false,
    },
  })

  // Fetch services and artists
  const { data: servicesData } = useQuery<Service[]>({
    queryKey: ['services'],
    queryFn: async () => {
      const res = await fetch('/api/services')
      if (!res.ok) throw new Error('Failed to fetch services')
      return res.json()
    },
  })

  const { data: artistsData } = useQuery<Artist[]>({
    queryKey: ['artists'],
    queryFn: async () => {
      const res = await fetch('/api/artists')
      if (!res.ok) throw new Error('Failed to fetch artists')
      return res.json()
    },
  })

  const selectedService = servicesData?.find((s) => s.id === selectedServiceId)

  // Create booking mutation
  const createBookingMutation = useMutation({
    mutationFn: async (formData: BookingFormData) => {
      // Combine date + time into ISO datetime
      if (!selectedDate) throw new Error('Date required')
      const timeInput = document.querySelector('input[type="time"][name="time"]') as HTMLInputElement
      if (!timeInput?.value) throw new Error('Time required')

      const [hours, minutes] = timeInput.value.split(':')
      const scheduledAt = new Date(selectedDate)
      scheduledAt.setHours(parseInt(hours, 10), parseInt(minutes, 10), 0, 0)

      const res = await fetch('/api/bookings', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          client_id: formData.client_id,
          artist_id: formData.artist_id,
          service_id: formData.service_id || null,
          scheduled_at: scheduledAt.toISOString(),
          duration_min: formData.duration_min,
          price_cents: selectedService?.base_price_cents ?? 0,
          deposit_cents: formData.send_deposit_link ? selectedService?.deposit_cents ?? 0 : 0,
          notes: formData.notes || null,
        }),
      })

      if (!res.ok) {
        const err = await res.json() as { error?: string }
        throw new Error(err.error ?? 'Failed to create booking')
      }

      return res.json() as Promise<{ data: { id: string; booking_token: string } }>
    },
    onSuccess: async (response) => {
      const bookingId = response.data.id
      void queryClient.invalidateQueries({ queryKey: ['bookings'] })

      // Send deposit link if requested
      const formValues = form.getValues()
      if (formValues.send_deposit_link && selectedService?.deposit_cents) {
        try {
          const checkoutRes = await fetch('/api/public/deposits/checkout', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              booking_token: response.data.booking_token,
              amount_cents: selectedService.deposit_cents,
            }),
          })

          if (checkoutRes.ok) {
            const { link } = await checkoutRes.json() as { link: string }
            toast.success('Booking created. Deposit link copied.', {
              description: link,
              action: {
                label: 'Copy',
                onClick: () => {
                  navigator.clipboard.writeText(link).catch(() => {})
                },
              },
              duration: 12000,
            })
          }
        } catch (err) {
          logger.error({ err }, 'deposit link failed')
          toast.success('Booking created', { description: 'Deposit link could not be generated' })
        }
      } else {
        toast.success('Booking created')
      }

      onOpenChange(false)
      onSuccess(bookingId)
    },
    onError: (err) => {
      logger.error({ err }, 'booking creation failed')
      toast.error(err instanceof Error ? err.message : 'Booking creation failed')
    },
  })

  const onSubmit = async (formData: BookingFormData) => {
    await createBookingMutation.mutateAsync(formData)
  }

  const handleServiceChange = (serviceId: string) => {
    setSelectedServiceId(serviceId)
    form.setValue('service_id', serviceId)
    const svc = servicesData?.find((s) => s.id === serviceId)
    if (svc) {
      form.setValue('duration_min', svc.duration_min)
    }
  }

  const handleDateSelect = (date: Date | undefined) => {
    setSelectedDate(date)
    setCalendarOpen(false)
  }

  // Format date for display
  const formattedDate = selectedDate
    ? selectedDate.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })
    : 'Select date'

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent className="w-full max-w-md">
        <SheetHeader>
          <SheetTitle>New booking</SheetTitle>
          <SheetDescription>Create a new appointment</SheetDescription>
        </SheetHeader>

        {!servicesData || !artistsData ? (
          <div className="space-y-3 mt-6">
            <Skeleton className="h-10 w-full rounded" />
            <Skeleton className="h-10 w-full rounded" />
            <Skeleton className="h-10 w-full rounded" />
            <Skeleton className="h-10 w-full rounded" />
          </div>
        ) : (
          <Form {...form}>
            <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4 mt-6">
              {/* Client Finder */}
              <div>
                <Label className="text-xs uppercase tracking-0.08em font-bold text-stone">Client</Label>
                <ClientFinder
                  onSelect={(client) => form.setValue('client_id', client.id)}
                  onNewClient={(data) => {
                    // Handle new client creation inline
                    form.setValue('client_id', data.id)
                  }}
                />
              </div>

              {/* Service */}
              <FormField
                control={form.control}
                name="service_id"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel className="text-xs uppercase tracking-0.08em font-bold text-stone">Service</FormLabel>
                    <Select value={field.value} onValueChange={handleServiceChange}>
                      <FormControl>
                        <SelectTrigger>
                          <SelectValue placeholder="Select service" />
                        </SelectTrigger>
                      </FormControl>
                      <SelectContent>
                        {servicesData.map((svc) => (
                          <SelectItem key={svc.id} value={svc.id}>
                            {svc.name} · {formatCurrency(svc.base_price_cents)}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                    <FormMessage />
                  </FormItem>
                )}
              />

              {/* Artist */}
              <FormField
                control={form.control}
                name="artist_id"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel className="text-xs uppercase tracking-0.08em font-bold text-stone">Artist</FormLabel>
                    <Select value={field.value} onValueChange={field.onChange}>
                      <FormControl>
                        <SelectTrigger>
                          <SelectValue placeholder="Select artist" />
                        </SelectTrigger>
                      </FormControl>
                      <SelectContent>
                        {artistsData.map((artist) => (
                          <SelectItem key={artist.id} value={artist.id}>
                            {artist.display_name}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                    <FormMessage />
                  </FormItem>
                )}
              />

              {/* Date + Time */}
              <div className="space-y-2">
                <Label className="text-xs uppercase tracking-0.08em font-bold text-stone">Date & Time</Label>
                <div className="flex gap-2">
                  <Popover open={calendarOpen} onOpenChange={setCalendarOpen}>
                    <PopoverTrigger asChild>
                      <Button variant="outline" className="flex-1 justify-start gap-2">
                        <Calendar className="h-4 w-4" />
                        {formattedDate}
                      </Button>
                    </PopoverTrigger>
                    <PopoverContent className="w-auto p-0" align="start">
                      <DayPicker
                        mode="single"
                        selected={selectedDate}
                        onSelect={handleDateSelect}
                        disabled={(date) => date < new Date(new Date().setHours(0, 0, 0, 0))}
                      />
                    </PopoverContent>
                  </Popover>

                  <div className="flex items-center gap-1 border border-border rounded-md px-3">
                    <Clock className="h-4 w-4 text-muted-foreground" />
                    <input
                      type="time"
                      name="time"
                      defaultValue={defaultStart ? `${defaultStart.getHours().toString().padStart(2, '0')}:${defaultStart.getMinutes().toString().padStart(2, '0')}` : '14:00'}
                      className="flex-1 bg-transparent text-sm outline-none"
                    />
                  </div>
                </div>
              </div>

              {/* Duration */}
              <FormField
                control={form.control}
                name="duration_min"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel className="text-xs uppercase tracking-0.08em font-bold text-stone">Duration</FormLabel>
                    <FormControl>
                      <div className="flex items-center gap-2">
                        <Input
                          {...field}
                          type="number"
                          min="15"
                          max="480"
                          step="15"
                          onChange={(e) => field.onChange(parseInt(e.target.value, 10))}
                          className="flex-1"
                        />
                        <span className="text-sm text-muted-foreground whitespace-nowrap">minutes</span>
                      </div>
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />

              {/* Notes */}
              <FormField
                control={form.control}
                name="notes"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel className="text-xs uppercase tracking-0.08em font-bold text-stone">Notes</FormLabel>
                    <FormControl>
                      <Textarea
                        {...field}
                        placeholder="Add any notes..."
                        className="resize-none"
                        rows={3}
                      />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />

              {/* Deposit Link */}
              {selectedService && selectedService.deposit_cents > 0 && (
                <FormField
                  control={form.control}
                  name="send_deposit_link"
                  render={({ field }) => (
                    <FormItem className="flex flex-row items-center justify-between rounded-lg border border-border p-3">
                      <div className="space-y-0.5">
                        <FormLabel className="text-xs uppercase tracking-0.08em font-bold text-stone">
                          Send deposit link
                        </FormLabel>
                        <p className="text-xs text-muted-foreground">
                          {formatCurrency(selectedService.deposit_cents)} deposit
                        </p>
                      </div>
                      <FormControl>
                        <Switch
                          checked={field.value}
                          onCheckedChange={field.onChange}
                        />
                      </FormControl>
                    </FormItem>
                  )}
                />
              )}

              {/* Submit */}
              <Button
                type="submit"
                className="w-full"
                disabled={createBookingMutation.isPending || !form.formState.isValid}
              >
                {createBookingMutation.isPending ? 'Creating...' : 'Create booking'}
              </Button>
            </form>
          </Form>
        )}
      </SheetContent>
    </Sheet>
  )
}

