'use client'

import { useState, useEffect } from 'react'
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import { toast } from 'sonner'
import { CalendarIcon, Clock } from 'lucide-react'
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
} from '@/components/ui/sheet'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Textarea } from '@/components/ui/textarea'
import { Switch } from '@/components/ui/switch'
import { Label } from '@/components/ui/label'
import { Skeleton } from '@/components/ui/skeleton'
import { Calendar } from '@/components/ui/calendar'
import { ClientFinder } from '@/components/booking/ClientFinder'
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover'
import { formatCurrency } from '@/lib/utils'
import { logger } from '@/lib/logger'

interface Service {
  id: string
  name: string
  duration_min: number
  base_price_cents: number
  deposit_cents: number
}

interface Artist {
  id: string
  display_name: string
  avatar_url: string | null
}

interface SmartBookingSheetProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  defaultStart?: Date | undefined
  defaultEnd?: Date | undefined
  defaultArtistId?: string | undefined
  editingId?: string | null | undefined
  onSuccess: (bookingId: string) => void
}

export function SmartBookingSheet({
  open,
  onOpenChange,
  defaultStart,
  defaultArtistId,
  onSuccess,
}: SmartBookingSheetProps) {
  const queryClient = useQueryClient()

  // Form state
  const [selectedDate, setSelectedDate] = useState<Date | undefined>(defaultStart)
  const [selectedTime, setSelectedTime] = useState<string>(
    defaultStart
      ? `${defaultStart.getHours().toString().padStart(2, '0')}:${defaultStart.getMinutes().toString().padStart(2, '0')}`
      : '14:00'
  )
  const [selectedServiceId, setSelectedServiceId] = useState<string>('')
  const [selectedArtistId, setSelectedArtistId] = useState<string>(defaultArtistId ?? '')
  const [selectedClientId, setSelectedClientId] = useState<string | null>(null)
  const [durationMin, setDurationMin] = useState<number>(60)
  const [notes, setNotes] = useState<string>('')
  const [sendDepositLink, setSendDepositLink] = useState<boolean>(false)
  const [calendarOpen, setCalendarOpen] = useState(false)

  // Fetch services and artists
  const { data: servicesData, isLoading: servicesLoading } = useQuery<Service[]>({
    queryKey: ['services'],
    queryFn: async () => {
      const res = await fetch('/api/services')
      if (!res.ok) throw new Error('Failed to fetch services')
      return res.json()
    },
    enabled: open,
  })

  const { data: artistsData, isLoading: artistsLoading } = useQuery<Artist[]>({
    queryKey: ['artists'],
    queryFn: async () => {
      const res = await fetch('/api/artists')
      if (!res.ok) throw new Error('Failed to fetch artists')
      return res.json()
    },
    enabled: open,
  })

  const selectedService = servicesData?.find((s) => s.id === selectedServiceId)

  // Auto-fill duration when service changes
  useEffect(() => {
    if (selectedService) {
      setDurationMin(selectedService.duration_min)
    }
  }, [selectedService])

  // Reset form when sheet opens
  useEffect(() => {
    if (open) {
      setSelectedDate(defaultStart)
      setSelectedTime(
        defaultStart
          ? `${defaultStart.getHours().toString().padStart(2, '0')}:${defaultStart.getMinutes().toString().padStart(2, '0')}`
          : '14:00'
      )
      setSelectedServiceId('')
      setSelectedArtistId(defaultArtistId ?? '')
      setSelectedClientId(null)
      setDurationMin(60)
      setNotes('')
      setSendDepositLink(false)
    }
  }, [open, defaultStart, defaultArtistId])

  // Create booking mutation
  const createBookingMutation = useMutation({
    mutationFn: async () => {
      if (!selectedClientId || !selectedArtistId || !selectedServiceId || !selectedDate) {
        throw new Error('Missing required fields')
      }

      const timeParts = selectedTime.split(':')
      const hours = timeParts[0] || '0'
      const minutes = timeParts[1] || '0'
      const scheduledAt = new Date(selectedDate)
      scheduledAt.setHours(parseInt(hours, 10), parseInt(minutes, 10), 0, 0)

      const res = await fetch('/api/bookings', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          client_id: selectedClientId,
          artist_id: selectedArtistId,
          service_id: selectedServiceId,
          scheduled_at: scheduledAt.toISOString(),
          duration_min: durationMin,
          price_cents: selectedService?.base_price_cents ?? 0,
          deposit_cents: sendDepositLink ? selectedService?.deposit_cents ?? 0 : 0,
          notes: notes || null,
        }),
      })

      if (!res.ok) {
        const err = await res.json() as { error?: string }
        throw new Error(err.error ?? 'Failed to create booking')
      }

      return res.json() as Promise<{ data: { id: string; booking_token: string } }>
    },
    onSuccess: async (response) => {
      const bookingId = response.data.id
      void queryClient.invalidateQueries({ queryKey: ['bookings'] })

      // Send deposit link if requested
      if (sendDepositLink && selectedService?.deposit_cents) {
        try {
          const checkoutRes = await fetch('/api/public/deposits/checkout', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              booking_token: response.data.booking_token,
              amount_cents: selectedService.deposit_cents,
            }),
          })

          if (checkoutRes.ok) {
            const { link } = await checkoutRes.json() as { link: string }
            toast.success('Booking created. Deposit link copied.', {
              description: link,
              action: {
                label: 'Copy',
                onClick: () => {
                  navigator.clipboard.writeText(link).catch(() => {})
                },
              },
              duration: 12000,
            })
          }
        } catch (err) {
          logger.error({ err }, 'deposit link failed')
          toast.success('Booking created', { description: 'Deposit link could not be generated' })
        }
      } else {
        toast.success('Booking created')
      }

      onOpenChange(false)
      onSuccess(bookingId)
    },
    onError: (err) => {
      logger.error({ err }, 'booking creation failed')
      toast.error(err instanceof Error ? err.message : 'Booking creation failed')
    },
  })

  const handleSubmit = async () => {
    await createBookingMutation.mutateAsync()
  }

  const handleDateSelect = (date: Date | undefined) => {
    setSelectedDate(date)
    setCalendarOpen(false)
  }

  const formattedDate = selectedDate
    ? selectedDate.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })
    : 'Select date'

  const isLoading = servicesLoading || artistsLoading
  const isFormValid = selectedClientId && selectedArtistId && selectedServiceId && selectedDate

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent className="w-full max-w-md">
        <SheetHeader>
          <SheetTitle>New booking</SheetTitle>
          <SheetDescription>Create a new appointment</SheetDescription>
        </SheetHeader>

        {isLoading ? (
          <div className="space-y-3 mt-6">
            <Skeleton className="h-10 w-full rounded" />
            <Skeleton className="h-10 w-full rounded" />
            <Skeleton className="h-10 w-full rounded" />
            <Skeleton className="h-10 w-full rounded" />
          </div>
        ) : (
          <div className="space-y-4 mt-6">
            {/* Client Finder */}
            <div>
              <Label className="text-xs uppercase tracking-wider font-bold text-stone">
                Client
              </Label>
              <ClientFinder
                selectedClientId={selectedClientId}
                onSelectClient={(id) => {
                  setSelectedClientId(id)
                }}
                onNewClient={(data) => {
                  // TODO: Create new client and use its ID
                  logger.error({ data }, 'new client creation not yet implemented')
                  toast.error('New client creation coming soon')
                }}
              />
            </div>

            {/* Service */}
            <div>
              <Label htmlFor="service" className="text-xs uppercase tracking-wider font-bold text-stone">
                Service
              </Label>
              <select
                id="service"
                value={selectedServiceId}
                onChange={(e) => setSelectedServiceId(e.target.value)}
                className="w-full mt-1 px-3 py-2 border border-border rounded-md bg-card text-sm outline-none"
              >
                <option value="">Select service</option>
                {servicesData?.map((svc) => (
                  <option key={svc.id} value={svc.id}>
                    {svc.name} · {formatCurrency(svc.base_price_cents)}
                  </option>
                ))}
              </select>
            </div>

            {/* Artist */}
            <div>
              <Label htmlFor="artist" className="text-xs uppercase tracking-wider font-bold text-stone">
                Artist
              </Label>
              <select
                id="artist"
                value={selectedArtistId}
                onChange={(e) => setSelectedArtistId(e.target.value)}
                className="w-full mt-1 px-3 py-2 border border-border rounded-md bg-card text-sm outline-none"
              >
                <option value="">Select artist</option>
                {artistsData?.map((artist) => (
                  <option key={artist.id} value={artist.id}>
                    {artist.display_name}
                  </option>
                ))}
              </select>
            </div>

            {/* Date & Time */}
            <div>
              <Label className="text-xs uppercase tracking-wider font-bold text-stone">
                Date & Time
              </Label>
              <div className="flex gap-2 mt-1">
                <Popover open={calendarOpen} onOpenChange={setCalendarOpen}>
                  <PopoverTrigger>
                    <Button variant="outline" className="flex-1 justify-start gap-2">
                      <CalendarIcon className="h-4 w-4" />
                      {formattedDate}
                    </Button>
                  </PopoverTrigger>
                  <PopoverContent className="w-auto p-0" align="start">
                    <Calendar
                      mode="single"
                      selected={selectedDate}
                      onSelect={handleDateSelect}
                      disabled={(date) => date < new Date(new Date().setHours(0, 0, 0, 0))}
                    />
                  </PopoverContent>
                </Popover>

                <div className="flex items-center gap-1 border border-border rounded-md px-3">
                  <Clock className="h-4 w-4 text-muted-foreground" />
                  <input
                    type="time"
                    value={selectedTime}
                    onChange={(e) => setSelectedTime(e.target.value)}
                    className="flex-1 bg-transparent text-sm outline-none"
                  />
                </div>
              </div>
            </div>

            {/* Duration */}
            <div>
              <Label htmlFor="duration" className="text-xs uppercase tracking-wider font-bold text-stone">
                Duration
              </Label>
              <div className="flex items-center gap-2 mt-1">
                <Input
                  id="duration"
                  type="number"
                  min="15"
                  max="480"
                  step="15"
                  value={durationMin}
                  onChange={(e) => setDurationMin(parseInt(e.target.value, 10))}
                />
                <span className="text-sm text-muted-foreground whitespace-nowrap">minutes</span>
              </div>
            </div>

            {/* Notes */}
            <div>
              <Label htmlFor="notes" className="text-xs uppercase tracking-wider font-bold text-stone">
                Notes
              </Label>
              <Textarea
                id="notes"
                placeholder="Add any notes..."
                value={notes}
                onChange={(e) => setNotes(e.target.value)}
                className="mt-1 resize-none"
                rows={3}
              />
            </div>

            {/* Deposit Link */}
            {selectedService && selectedService.deposit_cents > 0 && (
              <div className="flex flex-row items-center justify-between rounded-lg border border-border p-3">
                <div className="space-y-0.5">
                  <Label className="text-xs uppercase tracking-wider font-bold text-stone">
                    Send deposit link
                  </Label>
                  <p className="text-xs text-muted-foreground">
                    {formatCurrency(selectedService.deposit_cents)} deposit
                  </p>
                </div>
                <Switch
                  checked={sendDepositLink}
                  onCheckedChange={setSendDepositLink}
                />
              </div>
            )}

            {/* Submit */}
            <Button
              onClick={handleSubmit}
              className="w-full"
              disabled={createBookingMutation.isPending || !isFormValid}
            >
              {createBookingMutation.isPending ? 'Creating...' : 'Create booking'}
            </Button>
          </div>
        )}
      </SheetContent>
    </Sheet>
  )
}

'use client'

import { Download, MoreVertical } from 'lucide-react'
import { Button } from '@/components/ui/button'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'

interface CalendarOverflowMenuProps {
  studioId?: string | undefined
  rangeStart?: string | undefined
  rangeEnd?: string | undefined
}

export function CalendarOverflowMenu({ studioId, rangeStart, rangeEnd }: CalendarOverflowMenuProps) {
  function handleDownload() {
    const params = new URLSearchParams()
    if (studioId) params.set('studioId', studioId)
    if (rangeStart) params.set('start', rangeStart)
    if (rangeEnd) params.set('end', rangeEnd)
    const url = `/api/calendar/export?${params.toString()}`
    const a = document.createElement('a')
    a.href = url
    a.download = `inkos-calendar-${rangeStart ?? 'export'}.ics`
    a.click()
  }

  return (
    <DropdownMenu>
      <DropdownMenuTrigger>
        <Button
          variant="ghost"
          size="icon"
          className="h-8 w-8"
          aria-label="More options"
        >
          <MoreVertical className="h-4 w-4" />
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end">
        <DropdownMenuItem onClick={handleDownload} className="flex items-center gap-2">
          <Download className="h-4 w-4" />
          <span>Download calendar (.ics)</span>
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

'use client'

import dynamic from 'next/dynamic'
import { useCallback, useState } from 'react'
import { useRouter, useSearchParams } from 'next/navigation'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { toast } from 'sonner'
import { Skeleton } from '@/components/ui/skeleton'
import { SmartBookingSheet } from '@/components/calendar/SmartBookingSheet'
import type { CalendarBooking } from '@/components/calendar/CalendarView'
import { useCalendarDrawer } from '@/hooks/calendar/use-calendar-drawer'
import { PageShell } from '@/components/shared/PageShell'

// Must be ssr:false — FullCalendar uses browser globals
const CalendarView = dynamic(
  () =>
    import('@/components/calendar/CalendarView').then((mod) => mod.CalendarView),
  {
    ssr: false,
    loading: () => (
      <div className="flex-1 p-4 space-y-3">
        <div className="flex items-center gap-3">
          <Skeleton className="h-9 w-32 rounded-lg" />
          <Skeleton className="h-9 w-24 rounded-lg" />
          <Skeleton className="h-9 w-24 rounded-lg" />
          <div className="ml-auto flex gap-2">
            <Skeleton className="h-9 w-9 rounded-lg" />
            <Skeleton className="h-9 w-20 rounded-lg" />
            <Skeleton className="h-9 w-9 rounded-lg" />
          </div>
        </div>
        <Skeleton className="h-[60vh] w-full rounded-xl" />
      </div>
    ),
  }
)

// ── C7: URL search param helpers ────────────────────────────────────────────
function parseIds(value: string | null): string[] {
  if (!value) return []
  return value.split(',').filter(Boolean)
}

function serializeIds(ids: string[]): string {
  return ids.join(',')
}

export function CalendarPageClient() {
  const router = useRouter()
  const searchParams = useSearchParams()
  const queryClient = useQueryClient()

  // ── C7: Lift filter state into URL ─────────────────────────────────────
  const filterArtistIds = parseIds(searchParams.get('artists'))
  const filterStatuses = parseIds(searchParams.get('statuses'))
  const filterServiceIds = parseIds(searchParams.get('services'))

  function updateFilters(updates: {
    artists?: string[]
    statuses?: string[]
    services?: string[]
  }) {
    const next = new URLSearchParams(searchParams.toString())
    if (updates.artists !== undefined) {
      if (updates.artists.length > 0) {
        next.set('artists', serializeIds(updates.artists))
      } else {
        next.delete('artists')
      }
    }
    if (updates.statuses !== undefined) {
      if (updates.statuses.length > 0) {
        next.set('statuses', serializeIds(updates.statuses))
      } else {
        next.delete('statuses')
      }
    }
    if (updates.services !== undefined) {
      if (updates.services.length > 0) {
        next.set('services', serializeIds(updates.services))
      } else {
        next.delete('services')
      }
    }
    router.replace(`?${next.toString()}`, { scroll: false })
  }

  // ── Date range state ──────────────────────────────────────────────────
  const [rangeStart, setRangeStart] = useState<string>(() => {
    const today = new Date()
    today.setHours(0, 0, 0, 0)
    return today.toISOString()
  })
  const [rangeEnd, setRangeEnd] = useState<string>(() => {
    const tomorrow = new Date()
    tomorrow.setDate(tomorrow.getDate() + 1)
    tomorrow.setHours(0, 0, 0, 0)
    return tomorrow.toISOString()
  })

  // ── Drawer state ────────────────────────────────────────────────────────
  const {
    drawerOpen,
    setDrawerOpen,
    editingId,
    defaultStart,
    defaultEnd,
    defaultArtistId,
    openNew,
    openEdit,
  } = useCalendarDrawer()

  const {
    data,
    isLoading,
    error,
    refetch,
  } = useQuery<{ data: CalendarBooking[]; count: number }>({
    queryKey: ['bookings', 'calendar', rangeStart, rangeEnd, filterArtistIds, filterStatuses],
    queryFn: async () => {
      const params = new URLSearchParams()
      params.set('from', rangeStart)
      params.set('to', rangeEnd)
      if (filterArtistIds.length > 0) params.set('artist_ids', filterArtistIds.join(','))
      if (filterStatuses.length > 0) params.set('statuses', filterStatuses.join(','))

      const res = await fetch(`/api/bookings/calendar?${params.toString()}`)
      if (!res.ok) throw new Error('Failed to fetch bookings')
      return res.json() as Promise<{ data: CalendarBooking[]; count: number }>
    },
  })

  const rescheduleMutation = useMutation({
    mutationFn: async ({
      id,
      newStart,
      newEnd,
    }: {
      id: string
      newStart: Date
      newEnd: Date
    }) => {
      const durationMs = newEnd.getTime() - newStart.getTime()
      const duration_min = Math.round(durationMs / 60000)
      const res = await fetch(`/api/bookings/${id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          scheduled_at: newStart.toISOString(),
          duration_min,
        }),
      })
      if (!res.ok) {
        const err = await res.json() as { error?: string }
        throw new Error(err.error ?? 'Reschedule failed')
      }
      return res.json()
    },
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: ['bookings'] })
    },
  })

  const handleReschedule = useCallback(
    async (id: string, newStart: Date, newEnd: Date) => {
      await rescheduleMutation.mutateAsync({ id, newStart, newEnd })
    },
    [rescheduleMutation]
  )

  const bookings = data?.data ?? []
  const totalBookings = data?.count ?? 0

  return (
    <PageShell fullHeight>
      <CalendarView
        bookings={bookings}
        isLoading={isLoading}
        error={error ? (error instanceof Error ? error.message : 'Unknown error') : null}
        totalBookings={totalBookings}
        rangeStart={rangeStart}
        rangeEnd={rangeEnd}
        onViewDatesChange={(start: Date, end: Date) => {
          setRangeStart(start.toISOString())
          setRangeEnd(end.toISOString())
        }}
        filterArtistIds={filterArtistIds}
        filterStatuses={filterStatuses}
        filterServiceIds={filterServiceIds}
        onArtistFilterChange={(ids) => updateFilters({ artists: ids })}
        onStatusFilterChange={(statuses) => updateFilters({ statuses })}
        onServiceFilterChange={(ids) => updateFilters({ services: ids })}
        onNewAppointment={openNew}
        onEditAppointment={openEdit}
        onReschedule={handleReschedule}
        onRetry={() => {
          void refetch()
        }}
      />

      <SmartBookingSheet
        open={drawerOpen}
        onOpenChange={setDrawerOpen}
        defaultStart={defaultStart}
        defaultEnd={defaultEnd}
        defaultArtistId={defaultArtistId}
        editingId={editingId}
        onSuccess={() => {
          setDrawerOpen(false)
          toast.success('Booking created')
        }}
      />
    </PageShell>
  )
}

