  depositCents: number,
  depositPaid: boolean
): 'LIVE' | 'PAID' | 'HOLD' | null {
  if (status === 'in_progress') return 'LIVE'
  if (status === 'pending' && depositCents > 0 && !depositPaid) return 'HOLD'
