import { DayChairCard } from './DayChairCard'
import { useNowLine } from '@/hooks/calendar/use-now-line'
import type { ChairColumn, BlockedSlot } from '@/hooks/calendar/use-day-chair-columns'
import type { CalendarBooking } from '@/components/calendar/CalendarView'

interface DayChairGridProps {
  date: Date
  columns: ChairColumn[]
  onEventClick: (bookingId: string) => void
  onEmptySlotClick: (artistId: string, start: Date, end: Date) => void
  onReschedule: (id: string, newStart: Date, newEnd: Date, newArtistId?: string) => Promise<void>
  slotMinTime?: string // default "08:00"
  slotMaxTime?: string // default "22:00"
  onViewDatesChange?: (start: Date, end: Date) => void
}

const DEFAULT_SLOT_MIN_TIME = '08:00'
const DEFAULT_SLOT_MAX_TIME = '22:00'
const SLOT_HEIGHT_PX = 128 // 30-min slot = 128px

// Droppable 30-min slot cell
interface DayChairSlotProps {
  artistId: string
  slotStart: Date
  topPx: number
  onEmptyClick: (artistId: string, start: Date) => void
}

function DayChairSlot({ artistId, slotStart, topPx, onEmptyClick }: DayChairSlotProps) {
  const { setNodeRef, isOver } = useDroppable({
    id: `slot-${artistId}-${slotStart.toISOString()}`,
    data: { artistId, slotStart: slotStart.toISOString() },
  })

  return (
    <div
      ref={setNodeRef}
      className={cn(
        'absolute inset-x-0 h-[--calendar-slot-height] cursor-pointer transition-colors',
        isOver && 'bg-[var(--color-rust)]/10 ring-1 ring-[var(--color-rust)]/40'
      )}
      style={{ top: `${topPx}px` }}
      onClick={() => onEmptyClick(artistId, slotStart)}
    />
  )
}

export function DayChairGrid({
  date,
  columns,
  onEventClick,
  onEmptySlotClick,
  onReschedule,
  slotMinTime = DEFAULT_SLOT_MIN_TIME,
  slotMaxTime = DEFAULT_SLOT_MAX_TIME,
}: DayChairGridProps) {
  const [draggingId, setDraggingId] = useState<string | null>(null)
  const [selectedId, setSelectedId] = useState<string | null>(null)
  const resizeStartYRef = useRef<number | null>(null)
  const resizeStartDurationRef = useRef<number | null>(null)

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: { distance: 5 },
    })
  )

  const { topPx: nowLinePx, isToday } = useNowLine({
    date,
    slotMinTime,
    slotHeightPx: SLOT_HEIGHT_PX,
  })

  // Parse time strings to minutes
  const parseTime = (timeStr: string): number => {
    const parts = timeStr.split(':').map(Number)
    const h = parts[0] ?? 8
    const m = parts[1] ?? 0
    return h * 60 + m
  }

  const slotStartMin = parseTime(slotMinTime)
  const slotEndMin = parseTime(slotMaxTime)
  const totalSlots = (slotEndMin - slotStartMin) / 30

  // Build all bookings map for quick lookup
  const bookingsMap = useMemo(() => {
    const map = new Map<string, CalendarBooking & { artistId: string }>()
    columns.forEach((col) => {
      col.bookings.forEach((b) => {
        map.set(b.id, { ...b, artistId: col.artistId })
      })
    })
    return map
  }, [columns])

  const handleDragStart = useCallback((e: DragStartEvent) => {
    setDraggingId(String(e.active.id))
  }, [])

  const handleDragCancel = useCallback(() => {
    setDraggingId(null)
  }, [])

  const handleDragEnd = useCallback(
    async (e: DragEndEvent) => {
      const { active, over } = e
      setDraggingId(null)
      if (!over || !active.data.current) return

      const booking = active.data.current.booking as CalendarBooking
      const sourceArtistId = active.data.current.sourceArtistId as string
      const dropData = over.data.current as { artistId: string; slotStart: string } | undefined
      if (!dropData) return

      const newStart = new Date(dropData.slotStart)
      const newEnd = new Date(newStart.getTime() + booking.duration_min * 60_000)
      const newArtistId =
        dropData.artistId !== sourceArtistId ? dropData.artistId : undefined

      // Check if anything actually changed — skip if same-slot drop
      const originalStart = new Date(booking.scheduled_at)
      if (
        originalStart.getTime() === newStart.getTime() &&
        newArtistId === undefined
      ) {
        return
      }

      const originalEnd = new Date(booking.end_at)
      let undoUsed = false

      toast.success('Appointment rescheduled', {
        action: {
          label: 'Undo',
          onClick: () => {
            undoUsed = true
            onReschedule(booking.id, originalStart, originalEnd, sourceArtistId).catch(
              (err) => {
                logger.error({ err }, 'undo reschedule failed')
                toast.error('Failed to undo reschedule')
              }
            )
          },
        },
        duration: 6000,
      })

      try {
        await onReschedule(booking.id, newStart, newEnd, newArtistId)
      } catch (err) {
        if (undoUsed) return
        const msg = err instanceof Error ? err.message : 'Reschedule failed'
        if (msg.includes('time_slot_unavailable') || msg.includes('23P01')) {
          toast.error('That time slot is already booked')
        } else {
          toast.error('Failed to reschedule appointment')
        }
        logger.error({ err }, 'day grid reschedule failed')
      }
    },
    [onReschedule]
  )

  const handleResizeStart = useCallback(
    (e: React.PointerEvent, bookingId: string) => {
      e.preventDefault()
      e.stopPropagation()

      const booking = bookingsMap.get(bookingId)
      if (!booking) return

      resizeStartYRef.current = e.clientY
      resizeStartDurationRef.current = booking.duration_min

      const handlePointerMove = (_moveEvent: PointerEvent) => {
        // Resize visualization could go here for real-time feedback
      }

      const handlePointerUp = async (upEvent: PointerEvent) => {
        document.removeEventListener('pointermove', handlePointerMove)
        document.removeEventListener('pointerup', handlePointerUp)

        if (
          resizeStartYRef.current === null ||
          resizeStartDurationRef.current === null ||
          !booking
        ) {
          resizeStartYRef.current = null
          resizeStartDurationRef.current = null
          return
        }

        const dy = upEvent.clientY - resizeStartYRef.current
        const durationDelta = Math.round(dy / (SLOT_HEIGHT_PX / 2)) * 15
        const newDuration = Math.max(15, resizeStartDurationRef.current + durationDelta)

        resizeStartYRef.current = null
        resizeStartDurationRef.current = null

        if (newDuration === booking.duration_min) return

        const start = new Date(booking.scheduled_at)
        const end = new Date(start.getTime() + newDuration * 60_000)
        const originalEnd = new Date(booking.end_at)
        let undoUsed = false

        toast.success('Appointment duration updated', {
          action: {
            label: 'Undo',
            onClick: () => {
              undoUsed = true
              onReschedule(booking.id, start, originalEnd).catch((err) => {
                logger.error({ err }, 'undo resize failed')
                toast.error('Failed to undo resize')
              })
            },
          },
          duration: 6000,
        })

        try {
          await onReschedule(booking.id, start, end)
        } catch (err) {
          if (undoUsed) return
          const msg = err instanceof Error ? err.message : 'Resize failed'
          if (msg.includes('time_slot_unavailable') || msg.includes('23P01')) {
            toast.error('That time slot is already booked')
          } else {
            toast.error('Failed to update appointment duration')
          }
          logger.error({ err }, 'day grid resize failed')
        }
      }

      document.addEventListener('pointermove', handlePointerMove)
      document.addEventListener('pointerup', handlePointerUp)
    },
    [bookingsMap, onReschedule]
  )

  const getPositionStyle = (booking: CalendarBooking): React.CSSProperties => {
    const start = new Date(booking.scheduled_at)
    const startMinutes = start.getHours() * 60 + start.getMinutes()
    const offsetMinutes = startMinutes - slotStartMin

    return {
      top: `${(offsetMinutes / 30) * SLOT_HEIGHT_PX}px`,
      height: `${Math.max((booking.duration_min / 30) * SLOT_HEIGHT_PX, 32)}px`,
    }
  }

  const getBlockedPositionStyle = (blocked: BlockedSlot): React.CSSProperties => {
    const startDate = new Date(blocked.start_at)
    const endDate = new Date(blocked.end_at)
    const startMinutes = startDate.getHours() * 60 + startDate.getMinutes()
    const endMinutes = endDate.getHours() * 60 + endDate.getMinutes()
    const offsetMinutes = startMinutes - slotStartMin
    const durationMinutes = endMinutes - startMinutes

    return {
      top: `${(offsetMinutes / 30) * SLOT_HEIGHT_PX}px`,
      height: `${(durationMinutes / 30) * SLOT_HEIGHT_PX}px`,
    }
  }

  // Compute slot start Date for a given artist + slot index
  const getSlotStart = (slotIndex: number): Date => {
    const slotMinutes = slotStartMin + slotIndex * 30
    const d = new Date(date)
    d.setHours(Math.floor(slotMinutes / 60), slotMinutes % 60, 0, 0)
    return d
  }

  return (
    <DndContext
      sensors={sensors}
      collisionDetection={closestCenter}
      onDragStart={handleDragStart}
      onDragEnd={handleDragEnd}
      onDragCancel={handleDragCancel}
    >
      <div className="flex-1 overflow-auto bg-bone">
        {/* Time axis + grid */}
        <div className="flex">
          {/* Time column */}
          <div className="w-[--calendar-time-col-w] border-r border-border bg-bone sticky left-0 z-20 flex flex-col">
            <div className="h-[--calendar-chair-header-h] border-b border-border flex items-center justify-center text-xs font-bold text-stone">
              TIME
            </div>
            {Array.from({ length: totalSlots }).map((_, i) => {
              const minutes = slotStartMin + i * 30
              const hours = Math.floor(minutes / 60)
              const mins = minutes % 60
              const timeStr = `${hours.toString().padStart(2, '0')}:${mins.toString().padStart(2, '0')}`

              return (
                <div
                  key={timeStr}
                  className="h-[--calendar-slot-height] border-b border-border flex items-center justify-center text-xs text-muted-foreground"
                >
                  {timeStr}
                </div>
              )
            })}
          </div>

          {/* Chair columns grid */}
          <div className="flex-1 relative">
            {/* Header row */}
            <div
              className="grid border-b border-border"
              style={{
                gridTemplateColumns: `repeat(${columns.length}, 1fr)`,
                height: 'var(--calendar-chair-header-h)',
              }}
            >
              {columns.map((col) => (
                <div
                  key={col.artistId}
                  className={cn(
                    'border-r border-border flex items-center justify-center text-xs font-bold text-stone truncate px-2',
                    `artist-event-${col.colorIndex}`
                  )}
                  title={col.displayName}
                >
                  {col.displayName}
                </div>
              ))}
            </div>

            {/* Slot grid — bookings + droppable slots per column */}
            <div
              className="relative grid"
              style={{
                gridTemplateColumns: `repeat(${columns.length}, 1fr)`,
                height: `${totalSlots * SLOT_HEIGHT_PX}px`,
              }}
            >
              {columns.map((col) => (
                <div
                  key={col.artistId}
                  className="relative border-r border-border"
                >
                  {/* Dividers */}
                  {Array.from({ length: totalSlots }).map((_, i) => (
                    <div
                      key={`divider-${i}`}
                      className="absolute inset-x-0 border-b border-border/50 h-[--calendar-slot-height]"
                      style={{ top: `${i * SLOT_HEIGHT_PX}px` }}
                    />
                  ))}

                  {/* Droppable slot cells (click-to-create + drop targets) */}
                  {Array.from({ length: totalSlots }).map((_, i) => (
                    <DayChairSlot
                      key={`slot-${i}`}
                      artistId={col.artistId}
                      slotStart={getSlotStart(i)}
                      topPx={i * SLOT_HEIGHT_PX}
                      onEmptyClick={(artistId, start) => {
                        const end = new Date(start.getTime() + 30 * 60_000)
                        onEmptySlotClick(artistId, start, end)
                      }}
                    />
                  ))}

                  {/* Blocked slots */}
                  {col.blockedSlots.map((blocked) => (
                    <div
                      key={blocked.id}
                      className="chair-blocked-slot absolute inset-x-0 pointer-events-none"
                      style={getBlockedPositionStyle(blocked)}
                    />
                  ))}

                  {/* Bookings (above droppable slots) */}
                  {col.bookings.map((booking) => (
                    <div
                      key={booking.id}
                      className="absolute inset-x-1 z-10"
                      style={getPositionStyle(booking)}
                    >
                      <DayChairCard
                        booking={booking}
                        sourceArtistId={col.artistId}
                        isSelected={selectedId === booking.id}
                        onClick={(e) => {
                          e.stopPropagation()
                          setSelectedId(booking.id)
                          onEventClick(booking.id)
                        }}
                        onResizeStart={(e) => handleResizeStart(e, booking.id)}
                      />
                    </div>
                  ))}
                </div>
              ))}

              {/* NOW line — spans all columns, rendered once */}
              {isToday && nowLinePx >= 0 && (
                <div
                  className="chair-now-line"
                  style={{ top: `${nowLinePx}px` }}
                  aria-hidden="true"
                />
              )}
            </div>
          </div>
        </div>
      </div>

      <DragOverlay>
        {draggingId ? (() => {
          const booking = bookingsMap.get(draggingId)
          return booking ? (
            <div className="opacity-90 shadow-lift rounded-sm">
              <DayChairCard
                booking={booking}
                sourceArtistId={booking.artistId}
                isSelected
              />
            </div>
          ) : null
        })() : null}
      </DragOverlay>
    </DndContext>
  )
}

