import { useMemo } from 'react'
import { useQuery } from '@tanstack/react-query'
import type { CalendarBooking } from '@/components/calendar/CalendarView'

export interface BlockedSlot {
  id: string
  start_at: string
  end_at: string
}

export interface ChairColumn {
  artistId: string
  displayName: string
  avatarUrl: string | null
  colorIndex: number
  bookings: CalendarBooking[]
  blockedSlots: BlockedSlot[]
}

interface UseDayChairColumnsParams {
  date: Date
  bookings: CalendarBooking[]
  blockedBookings?: CalendarBooking[] // Unused, kept for API compat
  filterArtistIds: string[]
}

interface UseDayChairColumnsResult {
  columns: ChairColumn[]
  isLoadingBlocked: boolean
  error: Error | null
}

export function useDayChairColumns({
  date,
  bookings,
  filterArtistIds,
}: UseDayChairColumnsParams): UseDayChairColumnsResult {
  // Fetch blocked slots for the day
  const dateStr = date.toISOString().split('T')[0]
  const { data: blockedData, isLoading: isLoadingBlocked, error } = useQuery({
    queryKey: ['bookings', 'calendar', 'blocked-slots', dateStr],
    queryFn: async () => {
      const res = await fetch(`/api/bookings/calendar/blocked-slots?from=${dateStr}&to=${dateStr}`)
      if (!res.ok) throw new Error('Failed to fetch blocked slots')
      return res.json() as Promise<{ data: Array<{ artist_id: string; blocked: BlockedSlot[] }> }>
    },
    staleTime: 5 * 60_000, // 5 minutes
  })

  const columns: ChairColumn[] = useMemo(() => {
    // Group bookings by artist
    const artistMap = new Map<string, { bookings: CalendarBooking[]; artist: CalendarBooking['artist'] }>()

    bookings.forEach((b) => {
      const existing = artistMap.get(b.artist.id)
      if (existing) {
        existing.bookings.push(b)
      } else {
        artistMap.set(b.artist.id, {
          bookings: [b],
          artist: b.artist,
        })
      }
    })

    // Add artists with no bookings but have blocked slots
    if (blockedData?.data) {
      blockedData.data.forEach(({ artist_id }) => {
        if (!artistMap.has(artist_id)) {
          // We don't have full artist info, so skip — only show artists with bookings
        }
      })
    }

    // Apply artist filter
    let filtered = Array.from(artistMap.values())
    if (filterArtistIds.length > 0) {
      filtered = filtered.filter(({ artist }) => filterArtistIds.includes(artist.id))
    }

    // Sort by sort_order
    filtered.sort((a, b) => a.artist.sort_order - b.artist.sort_order)

    // Build columns
    return filtered.map(({ artist, bookings: artistBookings }) => {
      const colorIndex = ((artist.sort_order - 1) % 10) + 1
      const blockedSlots = blockedData?.data?.find(({ artist_id }) => artist_id === artist.id)?.blocked ?? []

      return {
        artistId: artist.id,
        displayName: artist.display_name,
        avatarUrl: artist.avatar_url,
        colorIndex,
        bookings: artistBookings,
        blockedSlots,
      }
    })
  }, [bookings, blockedData, filterArtistIds])

  return {
    columns,
    isLoadingBlocked,
    error: error instanceof Error ? error : null,
  }
}

