'use client'

import { useQuery } from '@tanstack/react-query'
import { toast } from 'sonner'
import { Link as LinkIcon } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { logger } from '@/lib/logger'

interface BookingLinksResponse {
  data: {
    studioUrl: string
    studioSlug: string
  }
}

export function CopyBookingLinkButton() {
  const { data, isLoading } = useQuery<BookingLinksResponse>({
    queryKey: ['booking-links'],
    queryFn: async () => {
      const res = await fetch('/api/booking-links')
      if (!res.ok) throw new Error('Failed to fetch booking link')
      return res.json() as Promise<BookingLinksResponse>
    },
    staleTime: 10 * 60_000,
  })

  const handleCopy = () => {
    const url = data?.data?.studioUrl
    if (!url) {
      toast.error('Booking link not available')
      return
    }
    navigator.clipboard.writeText(url).then(
      () => {
        toast.success('Booking link copied', { description: url })
      },
      (err) => {
        logger.error({ err }, 'clipboard write failed')
        toast.error('Failed to copy booking link')
      }
    )
  }

  return (
    <Button
      variant="outline"
      size="sm"
      onClick={handleCopy}
      disabled={isLoading || !data?.data?.studioUrl}
    >
      <LinkIcon className="mr-2 h-4 w-4" />
      Copy booking link
    </Button>
  )
}

