/**
 * SMS message templates for InkOS.
 *
 * All templates return plain-text strings (SMS has no HTML).
 * Max 160 chars per segment — keep messages short.
 * Emojis are intentionally avoided to ensure GSM-7 encoding and single segments.
 *
 * Usage:
 *   import { smsTemplates } from '@/lib/sms/templates'
 *   const body = smsTemplates.bookingConfirmation({ ... })
 *   await sendSms({ to: phone, body })
 */

export interface BookingConfirmationSmsData {
  clientFirstName: string
  studioName: string
  serviceName: string
  artistName: string
  scheduledAt: Date
  bookingReference: string
}

export interface ReminderSmsData {
  clientFirstName: string
  studioName: string
  serviceName: string
  artistName: string
  scheduledAt: Date
  hoursUntil: number
}

export interface DepositReceiptSmsData {
  clientFirstName: string
  studioName: string
  depositAmount: string
  bookingReference: string
}

export interface CancellationSmsData {
  clientFirstName: string
  studioName: string
  serviceName: string
  scheduledAt: Date
  reason?: string
}

function formatSmsDate(date: Date): string {
  return date.toLocaleDateString('en-US', {
    weekday: 'short',
    month: 'short',
    day: 'numeric',
    hour: 'numeric',
    minute: '2-digit',
  })
}

export const smsTemplates = {
  /**
   * Sent when a new booking is created (public flow or internal).
   * ~140 chars typical.
   */
  bookingConfirmation(data: BookingConfirmationSmsData): string {
    return (
      `Hi ${data.clientFirstName}, your ${data.serviceName} booking with ` +
      `${data.artistName} at ${data.studioName} is confirmed for ` +
      `${formatSmsDate(data.scheduledAt)}. Ref: ${data.bookingReference}`
    )
  },

  /**
   * Reminder sent 24h before the appointment.
   * ~120 chars typical.
   */
  reminder24h(data: ReminderSmsData): string {
    return (
      `Reminder: Your ${data.serviceName} with ${data.artistName} ` +
      `at ${data.studioName} is tomorrow at ` +
      `${formatSmsDate(data.scheduledAt)}. See you then!`
    )
  },

  /**
   * Reminder sent 2h before the appointment.
   * ~110 chars typical.
   */
  reminder2h(data: ReminderSmsData): string {
    return (
      `Heads up! Your ${data.serviceName} with ${data.artistName} ` +
      `at ${data.studioName} starts in 2 hours ` +
      `(${formatSmsDate(data.scheduledAt)}).`
    )
  },

  /**
   * Sent when a deposit payment is received.
   * ~100 chars typical.
   */
  depositReceipt(data: DepositReceiptSmsData): string {
    return (
      `Deposit of ${data.depositAmount} received for booking ${data.bookingReference} ` +
      `at ${data.studioName}. You're all set!`
    )
  },

  /**
   * Sent when a booking is cancelled by the studio.
   * ~120 chars typical.
   */
  cancellation(data: CancellationSmsData): string {
    const reasonPart = data.reason ? ` Reason: ${data.reason}.` : ''
    return (
      `Hi ${data.clientFirstName}, your ${data.serviceName} on ` +
      `${formatSmsDate(data.scheduledAt)} at ${data.studioName} ` +
      `has been cancelled.${reasonPart}`
    )
  },
} as const

