// Scroll-to-now on mount when viewing today — center NOW line in viewport
useEffect(() => {
  if (!isToday || nowLinePx < 0) return
  const el = scrollContainerRef.current
  if (!el) return
  const viewportHeight = el.clientHeight
  // Account for the sticky header row (~3rem)
  const headerOffset = 48
  const target = Math.max(0, nowLinePx - viewportHeight / 2 + headerOffset)
  el.scrollTo({ top: target, behavior: 'smooth' })
  // Only on first mount / when date switches — NOT on every minute-tick.
  // eslint-disable-next-line react-hooks/exhaustive-deps
}, [date, isToday])

