        isOver && !isOccupied && 'bg-[var(--color-rust)]/10 ring-1 ring-[var(--color-rust)]/40',
        dimmedByDrag && 'bg-stone/10'
      )}
      style={{ top: `${topPx}px`, height: `${heightPx}px` }}
      onClick={() => {
        if (isOccupied) return
        onEmptyClick(artistId, slotStart)
      }}
    />
  )
}

