  const totalFifteen = totalSlots * 2
  const map = new Map<string, boolean[]>()

  columns.forEach((col) => {
    const flags: boolean[] = new Array(totalFifteen).fill(false)

    const allBusy: Array<{ start: number; end: number }> = []
    // Bookings block their span — exclude the booking currently being dragged
    col.bookings.forEach((b) => {
      if (draggingId === b.id) return
      if (b.status === 'cancelled') return
      const s = new Date(b.scheduled_at)
      const e = new Date(b.end_at)
      allBusy.push({
        start: s.getHours() * 60 + s.getMinutes(),
        end: e.getHours() * 60 + e.getMinutes(),
      })
    })
    // Blocked slots also block
    col.blockedSlots.forEach((bs) => {
      const s = new Date(bs.start_at)
      const e = new Date(bs.end_at)
      allBusy.push({
        start: s.getHours() * 60 + s.getMinutes(),
        end: e.getHours() * 60 + e.getMinutes(),
      })
    })

    for (let i = 0; i < totalFifteen; i++) {
      const slotStartMins = slotStartMin + i * 15
      const slotEndMins = slotStartMins + 15
      flags[i] = allBusy.some(
        ({ start, end }) => start < slotEndMins && end > slotStartMins
      )
    }

    map.set(col.artistId, flags)
  })

