import { requireFeatureRpc, FeatureGateError } from '@/lib/billing/feature-gate'
import { logger } from '@/lib/logger'
import { createClient, getAuthenticatedUser } from '@/lib/supabase/server'

const QuerySchema = z.object({
  from: z.string().datetime(),
  to: z.string().datetime(),
  artist_ids: z.string().optional(),
  statuses: z.string().optional(),
})

const VALID_STATUSES = [
  'pending',
  'confirmed',
  'in_progress',
  'completed',
  'cancelled',
  'no_show',
] as const

export async function GET(req: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  try {
    const url = new URL(req.url)
    const parsed = QuerySchema.safeParse({
      from: url.searchParams.get('from'),
      to: url.searchParams.get('to'),
      artist_ids: url.searchParams.get('artist_ids') ?? undefined,
      statuses: url.searchParams.get('statuses') ?? undefined,
    })

    if (!parsed.success) {
      return NextResponse.json({ error: 'Invalid query params' }, { status: 400 })
    }

    const { from, to, artist_ids, statuses } = parsed.data
    const supabase = await createClient()

    try {
      await requireFeatureRpc(supabase, authUser.studioId, 'calendar')
    } catch (err) {
      if (err instanceof FeatureGateError) {
        return NextResponse.json(
          { error: 'Calendar feature not available on your plan' },
          { status: 403 }
        )
      }
      throw err
    }

    let query = supabase
      .from('bookings')
      .select(
        `
        id, scheduled_at, end_at, duration_min, status, deposit_cents, deposit_paid,
        project_id, session_number,
        client:clients(id, first_name, last_name),
        artist:artists(id, display_name, avatar_url, sort_order),
        service:services(id, name, color),
        project:projects(name)
      `,
        { count: 'exact' }
      )
      .eq('studio_id', authUser.studioId)
      .gte('scheduled_at', from)
      .lt('scheduled_at', to)
      .order('scheduled_at', { ascending: true })
      .limit(2000)

    if (artist_ids) {
      const ids = artist_ids.split(',').filter(Boolean)
      if (ids.length > 0) query = query.in('artist_id', ids)
    }

    if (statuses) {
      const statusList = statuses
        .split(',')
        .filter((s): s is (typeof VALID_STATUSES)[number] =>
          VALID_STATUSES.includes(s as (typeof VALID_STATUSES)[number])
        )
      if (statusList.length > 0) {
        query = query.in('status', statusList)
      }
    }

    const { data, error, count } = await query

    if (error) {
      logger.error({ err: error }, 'calendar bookings fetch failed')
      return NextResponse.json({ error: 'Failed to fetch bookings' }, { status: 500 })
    }

    return NextResponse.json({
      data: data ?? [],
      count: count ?? 0,
    })
  } catch (err) {
    logger.error({ err }, 'calendar bookings unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

