import { NextRequest, NextResponse } from 'next/server'
import { z } from 'zod'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { createClient, getAuthenticatedUser } from '@/lib/supabase/server'

const QuerySchema = z.object({
  from: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
  to: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
})

interface BlockedSlot {
  id: string
  start_at: string
  end_at: string
  kind: 'time_off' | 'blocked_date'
  reason: string
}

interface BlockedSlotsResponse {
  data: Array<{
    artist_id: string
    blocked: BlockedSlot[]
  }>
}

export async function GET(
  req: NextRequest
): Promise<NextResponse<BlockedSlotsResponse | { error: string }>> {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  try {
    const url = new URL(req.url)
    const parsed = QuerySchema.safeParse({
      from: url.searchParams.get('from'),
      to: url.searchParams.get('to'),
    })

    if (!parsed.success) {
      return NextResponse.json({ error: 'Invalid query params' }, { status: 400 })
    }

    const { from, to } = parsed.data
    const supabase = await createClient()

    // time_off — approved absences with timestamp ranges
    const { data: timeOff, error: timeOffError } = await supabase
      .from('artist_time_off')
      .select('id, artist_id, start_at, end_at')
      .eq('studio_id', authUser.studioId)
      .eq('status', 'approved')
      .gte('end_at', from)
      .lte('start_at', to)

    if (timeOffError) {
      logger.error({ err: timeOffError }, 'time_off fetch failed')
      return NextResponse.json({ error: 'Failed to fetch time off' }, { status: 500 })
    }

    // artist_blocked_dates — single-day blocks, expand to full-day start/end
    const { data: blockedDates, error: blockedError } = await supabase
      .from('artist_blocked_dates')
      .select('id, artist_id, blocked_date, reason')
      .eq('studio_id', authUser.studioId)
      .gte('blocked_date', from)
      .lte('blocked_date', to)

    if (blockedError) {
      logger.error({ err: blockedError }, 'blocked_dates fetch failed')
      return NextResponse.json({ error: 'Failed to fetch blocked dates' }, { status: 500 })
    }

    // Aggregate by artist_id
    const byArtist = new Map<string, BlockedSlot[]>()

    for (const slot of timeOff ?? []) {
      const list = byArtist.get(slot.artist_id) ?? []
      list.push({
        id: slot.id,
        start_at: slot.start_at,
        end_at: slot.end_at,
        kind: 'time_off',
        reason: 'Time off',
      })
      byArtist.set(slot.artist_id, list)
    }

    for (const slot of blockedDates ?? []) {
      // Expand a single date to a full-day timestamp range (00:00 → 24:00 UTC)
      const startAt = `${slot.blocked_date}T00:00:00.000Z`
      const endAt = `${slot.blocked_date}T23:59:59.999Z`
      const list = byArtist.get(slot.artist_id) ?? []
      list.push({
        id: slot.id,
        start_at: startAt,
        end_at: endAt,
        kind: 'blocked_date',
        reason: slot.reason ?? 'Not available',
      })
      byArtist.set(slot.artist_id, list)
    }

    const result: BlockedSlotsResponse = {
      data: Array.from(byArtist.entries()).map(([artist_id, blocked]) => ({
        artist_id,
        blocked,
      })),
    }

    return NextResponse.json(result)
  } catch (err) {
    logger.error({ err }, 'blocked slots unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

