'use client'

/**
 * useBookingsRealtime — subscribes to Postgres changes on the `bookings`
 * table for a single studio and invalidates the calendar bookings query
 * on any INSERT / UPDATE / DELETE so the grid stays in sync when another
 * user (front desk + owner, for example) edits a booking.
 */

import { useEffect } from 'react'
import { useQueryClient } from '@tanstack/react-query'
import { createClient } from '@/lib/supabase/client'

export function useBookingsRealtime(studioId: string | undefined): void {
  const queryClient = useQueryClient()

  useEffect(() => {
    if (!studioId) return

    const supabase = createClient()

    const channel = supabase
      .channel(`bookings:${studioId}`)
      .on(
        'postgres_changes',
        {
          event: '*',
          schema: 'public',
          table: 'bookings',
          filter: `studio_id=eq.${studioId}`,
        },
        () => {
          // Any change to bookings for this studio invalidates the calendar query.
          // The actual fetch is debounced by React Query's staleTime + refetch policy.
          void queryClient.invalidateQueries({ queryKey: ['bookings'] })
        }
      )
      .subscribe()

    return () => {
      void supabase.removeChannel(channel)
    }
  }, [studioId, queryClient])
}

