'use client'

/**
 * useBookingsRealtime — subscribes to Postgres changes on the `bookings`
 * table for a single studio and invalidates the calendar bookings query
 * on any INSERT / UPDATE / DELETE so the grid stays in sync when another
 * user (front desk + owner, for example) edits a booking.
 *
 * Invalidation is scoped to `['bookings', 'calendar']` to avoid refetching
 * unrelated bookings queries on other pages (e.g., client detail, reports).
 *
 * Invalidation is debounced (250ms trailing) so a burst of rapid updates —
 * e.g., another user dragging a card in quick succession — collapses into
 * a single refetch instead of N.
 */

import { useEffect, useRef } from 'react'
import { useQueryClient } from '@tanstack/react-query'
import { createClient } from '@/lib/supabase/client'

const DEBOUNCE_MS = 250

export function useBookingsRealtime(studioId: string | undefined): void {
  const queryClient = useQueryClient()
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  useEffect(() => {
    if (!studioId) return

    const supabase = createClient()

    const scheduleInvalidate = () => {
      if (timerRef.current) clearTimeout(timerRef.current)
      timerRef.current = setTimeout(() => {
        void queryClient.invalidateQueries({ queryKey: ['bookings', 'calendar'] })
      }, DEBOUNCE_MS)
    }

    const channel = supabase
      .channel(`bookings:${studioId}`)
      .on(
        'postgres_changes',
        {
          event: '*',
          schema: 'public',
          table: 'bookings',
          filter: `studio_id=eq.${studioId}`,
        },
        () => {
          scheduleInvalidate()
        }
      )
      .subscribe()

    return () => {
      if (timerRef.current) clearTimeout(timerRef.current)
      void supabase.removeChannel(channel)
    }
  }, [studioId, queryClient])
}

