import { useMemo } from 'react'
import { useQuery } from '@tanstack/react-query'
import type { CalendarBooking } from '@/components/calendar/CalendarView'

export interface BlockedSlot {
  id: string
  start_at: string
  end_at: string
}

export interface ChairColumn {
  artistId: string
  displayName: string
  avatarUrl: string | null
  colorIndex: number
  bookings: CalendarBooking[]
  blockedSlots: BlockedSlot[]
}

interface ActiveArtist {
  id: string
  display_name: string
  avatar_url: string | null
  sort_order: number
  status: string
}

interface UseDayChairColumnsParams {
  date: Date
  bookings: CalendarBooking[]
  filterArtistIds: string[]
}

interface UseDayChairColumnsResult {
  columns: ChairColumn[]
  isLoadingBlocked: boolean
  isLoadingArtists: boolean
  error: Error | null
}

export function useDayChairColumns({
  date,
  bookings,
  filterArtistIds,
}: UseDayChairColumnsParams): UseDayChairColumnsResult {
  const dateStr = date.toISOString().split('T')[0]

  // Fetch all active artists (for chair columns)
  const {
    data: artistsData,
    isLoading: isLoadingArtists,
    error: artistsError,
  } = useQuery({
    queryKey: ['artists', 'active'],
    queryFn: async () => {
      const res = await fetch('/api/artists?status=active')
      if (!res.ok) throw new Error('Failed to fetch artists')
      const json = (await res.json()) as { data: ActiveArtist[] }
      return json.data
    },
    staleTime: 5 * 60_000,
  })

  // Fetch blocked slots for the day
  const {
    data: blockedData,
    isLoading: isLoadingBlocked,
    error: blockedError,
  } = useQuery({
    queryKey: ['bookings', 'calendar', 'blocked-slots', dateStr],
    queryFn: async () => {
      const res = await fetch(
        `/api/bookings/calendar/blocked-slots?from=${dateStr}&to=${dateStr}`
      )
      if (!res.ok) throw new Error('Failed to fetch blocked slots')
      return res.json() as Promise<{
        data: Array<{ artist_id: string; blocked: BlockedSlot[] }>
      }>
    },
    staleTime: 5 * 60_000,
  })

  const columns: ChairColumn[] = useMemo(() => {
    if (!artistsData || artistsData.length === 0) return []

    // Group bookings by artist
    const bookingsByArtist = new Map<string, CalendarBooking[]>()
    bookings.forEach((b) => {
      const arr = bookingsByArtist.get(b.artist.id) ?? []
      arr.push(b)
      bookingsByArtist.set(b.artist.id, arr)
    })

    // Group blocked slots by artist
    const blockedByArtist = new Map<string, BlockedSlot[]>()
    blockedData?.data?.forEach(({ artist_id, blocked }) => {
      blockedByArtist.set(artist_id, blocked)
    })

    // Apply artist filter
    let filtered = artistsData
    if (filterArtistIds.length > 0) {
      filtered = filtered.filter((a) => filterArtistIds.includes(a.id))
    }

    // Sort by sort_order, build columns
    return [...filtered]
      .sort((a, b) => a.sort_order - b.sort_order)
      .map((artist) => ({
        artistId: artist.id,
        displayName: artist.display_name,
        avatarUrl: artist.avatar_url,
        colorIndex: ((artist.sort_order - 1) % 10) + 1,
        bookings: bookingsByArtist.get(artist.id) ?? [],
        blockedSlots: blockedByArtist.get(artist.id) ?? [],
      }))
  }, [artistsData, bookings, blockedData, filterArtistIds])

  const error =
    (artistsError instanceof Error && artistsError) ||
    (blockedError instanceof Error && blockedError) ||
    null

  return {
    columns,
    isLoadingBlocked,
    isLoadingArtists,
    error,
  }
}

