type BookingsQuery = { data: CalendarBooking[]; count: number }

// Minimal artist shape from /api/artists?status=active — cached by the
// use-day-chair-columns hook, reused here for optimistic cross-column drags
// so we don't leave the card showing the OLD artist's name/avatar until refetch.
interface CachedActiveArtist {
  id: string
  display_name: string
  avatar_url: string | null
  sort_order: number
}

const rescheduleMutation = useMutation({
  // Serialize concurrent drags — react-query runs mutations with the same
  // scope id sequentially, so `onMutate` snapshots always see pre-mutation
  // state (never another in-flight mutation's optimistic writes).
  scope: { id: 'reschedule-booking' },
  mutationFn: async ({
    id,
    newStart,
    newEnd,
    newArtistId,
    suppressNotifications,
  }: {
    id: string
    newStart: Date
    newEnd: Date
    newArtistId?: string
    suppressNotifications?: boolean
  }) => {
    const durationMs = newEnd.getTime() - newStart.getTime()
    const duration_min = Math.round(durationMs / 60000)
    const body: Record<string, unknown> = {
      scheduled_at: newStart.toISOString(),
      duration_min,
    }
    if (newArtistId) body.artist_id = newArtistId
    if (suppressNotifications) body.suppress_notifications = true
    const res = await fetch(`/api/bookings/${id}`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    })
    if (!res.ok) {
      const err = await res.json() as { error?: string }
      throw new Error(err.error ?? 'Reschedule failed')
    }
    return res.json()
  },
  onMutate: async ({ id, newStart, newEnd, newArtistId }) => {
    await queryClient.cancelQueries({ queryKey: ['bookings', 'calendar'] })

    const snapshots = queryClient.getQueriesData<BookingsQuery>({
      queryKey: ['bookings', 'calendar'],
    })

    // Pull the full target artist from cache so we spread correct
    // display_name / avatar_url / sort_order on cross-column drags.
    const artistsCache =
      queryClient.getQueryData<CachedActiveArtist[]>(['artists', 'active']) ?? []
    const targetArtist = newArtistId
      ? artistsCache.find((a) => a.id === newArtistId)
      : undefined

    queryClient.setQueriesData<BookingsQuery>(
      { queryKey: ['bookings', 'calendar'] },
      (old) => {
        if (!old) return old
        return {
          ...old,
          data: old.data.map((b) => {
            if (b.id !== id) return b
            const durationMin = Math.round(
              (newEnd.getTime() - newStart.getTime()) / 60000
            )
            return {
              ...b,
              scheduled_at: newStart.toISOString(),
              end_at: newEnd.toISOString(),
              duration_min: durationMin,
              ...(newArtistId && b.artist.id !== newArtistId
                ? {
                    artist: targetArtist
                      ? {
                          id: targetArtist.id,
                          display_name: targetArtist.display_name,
                          avatar_url: targetArtist.avatar_url,
                          sort_order: targetArtist.sort_order,
                        }
                      : { ...b.artist, id: newArtistId },
                  }
                : {}),
            }
          }),
        }
      }
    )

