import { useEffect, useState } from 'react'

interface UseNowLineParams {
  date: Date
  slotMinTime: string // "08:00"
  slotHeightPx: number // height of each 30-min slot in pixels
}

interface UseNowLineResult {
  topPx: number // pixel offset from top, -1 if not today
  isToday: boolean
  label: string
}

export function useNowLine({
  date,
  slotMinTime,
  slotHeightPx,
}: UseNowLineParams): UseNowLineResult {
  const [result, setResult] = useState<UseNowLineResult>(() => computeNowLine(date, slotMinTime, slotHeightPx))

  useEffect(() => {
    const update = () => {
      setResult(computeNowLine(date, slotMinTime, slotHeightPx))
    }

    // Initial compute
    update()

    // Update every 60 seconds
    const interval = setInterval(update, 60000)
    return () => clearInterval(interval)
  }, [date, slotMinTime, slotHeightPx])

  return result
}

function computeNowLine(
  date: Date,
  slotMinTime: string,
  slotHeightPx: number
): UseNowLineResult {
  const now = new Date()
  const dateAtMidnight = new Date(date)
  dateAtMidnight.setHours(0, 0, 0, 0)

  const isToday = now.toDateString() === dateAtMidnight.toDateString()

  if (!isToday) {
    return { topPx: -1, isToday: false, label: '' }
  }

  // Parse slotMinTime (e.g., "08:00")
  const parts = slotMinTime.split(':').map(Number)
  const minTimeHours = parts[0] ?? 8
  const minTimeMinutes = parts[1] ?? 0
  const slotStartMinutes = minTimeHours * 60 + minTimeMinutes

  // Current time in minutes from midnight
  const currentMinutes = now.getHours() * 60 + now.getMinutes()

  // Offset from slot start time
  const offsetMinutes = currentMinutes - slotStartMinutes

  // If before slot start or after slot end, hide the line
  if (offsetMinutes < 0) {
    return { topPx: -1, isToday: false, label: '' }
  }

  // Calculate pixel offset (each 30-min slot = slotHeightPx)
  const topPx = (offsetMinutes / 30) * slotHeightPx

  // Format label
  const label = `NOW · ${now.toLocaleTimeString('en-US', {
    hour: 'numeric',
    minute: '2-digit',
    hour12: true,
  })}`

  return { topPx, isToday: true, label }
}

