function getClientMeta(client: Client): string {
  const preferredContact = getContactValue(
    client.preferred_contact ?? 'email',
    client.email,
    client.phone,
  )
  const contact = preferredContact ?? client.email ?? client.phone
  const source = formatSource(client.source)
  const sourceText = source === '—' ? null : source
  const parts = [contact, sourceText].filter(Boolean)
  return parts.length > 0 ? parts.join(' · ') : 'No contact added'
}

