import react from '@vitejs/plugin-react'
import tsconfigPaths from 'vite-tsconfig-paths'

export default defineConfig({
  plugins: [react(), tsconfigPaths()],
  test: {
    environment: 'jsdom',
    globals: true,
    setupFiles: ['./tests/setup.ts'],
    // Use threads pool — forks caused OOM with never-resolving promises in tests
    pool: 'threads',
    poolOptions: {
      threads: {
        // Isolate each test file — prevents module-mock contamination
        isolate: true,
        minThreads: 1,
        maxThreads: 4,
      },
    },
    coverage: {
      provider: 'v8',
      reporter: ['text', 'html'],
      thresholds: { lines: 70, functions: 70, branches: 65 },
      exclude: [
        '**/*.config.*',
        '**/components/ui/**',
        '**/.next/**',
        '**/node_modules/**',
        '**/tests/e2e/**',
        '**/tests/smoke/**',
      ],
    },
    exclude: [
