'use client'

import { useDraggable } from '@dnd-kit/core'
import { CSS } from '@dnd-kit/utilities'
import { cn } from '@/lib/utils'
import type { CalendarBooking } from '@/components/calendar/CalendarView'

interface DayChairCardProps {
  booking: CalendarBooking
  sourceArtistId: string
  isSelected?: boolean
  onClick?: (e: React.MouseEvent | React.KeyboardEvent) => void
  onResizeStart?: (e: React.PointerEvent) => void
}

function getStatusPill(
  status: string,
  depositCents: number | null | undefined,
  depositPaid: boolean | null | undefined
): 'LIVE' | 'PAID' | 'HOLD' | null {
  if (status === 'in_progress') return 'LIVE'
  if (status === 'pending' && (depositCents ?? 0) > 0 && !(depositPaid ?? false)) return 'HOLD'
  if (status === 'completed' && depositPaid) return 'PAID'
  return null
}

// Human-readable deadline countdown for HOLD bookings — "4h left" / "2d left" / "Expired".
function formatDeadlineCountdown(deadline: string): string {
  const msRemaining = new Date(deadline).getTime() - Date.now()
  if (msRemaining <= 0) return 'Expired'
  const hours = Math.round(msRemaining / 3_600_000)
  if (hours < 1) return '<1h left'
  if (hours < 24) return `${hours}h left`
  return `${Math.floor(hours / 24)}d left`
}

export function DayChairCard({
  booking,
  sourceArtistId,
  isSelected,
  onClick,
  onResizeStart,
}: DayChairCardProps) {
  const { setNodeRef, attributes, listeners, isDragging, transform } = useDraggable({
    id: booking.id,
    data: { booking, sourceArtistId },
  })

  // Enter opens the edit sheet (keyboard equivalent of click).
  // Space is reserved for dnd-kit's KeyboardSensor drag activation — proxy it through.
  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && onClick) {
      e.preventDefault()
      onClick(e)
      return
    }
    // Delegate remaining keys (Space, arrows) to dnd-kit's KeyboardSensor listener
    if (listeners && typeof listeners.onKeyDown === 'function') {
      listeners.onKeyDown(e)
    }
  }

  const startTime = new Date(booking.scheduled_at).toLocaleTimeString('en-US', {
    hour: 'numeric',
    minute: '2-digit',
    hour12: true,
  })

  const isCancelled = booking.status === 'cancelled'
  const statusPill = getStatusPill(booking.status, booking.deposit_cents, booking.deposit_paid)

  return (
    <div
      ref={setNodeRef}
      style={{
        transform: CSS.Translate.toString(transform),
        opacity: isDragging ? 0.5 : 1,
      }}
      className={cn(
        'absolute left-0 right-0 rounded-sm border border-border bg-card p-1.5 overflow-hidden',
        'cursor-grab active:cursor-grabbing transition-opacity',
        'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--color-rust)]',
        isSelected && 'ring-2 ring-rust',
        isCancelled && 'opacity-60'
      )}
      {...attributes}
      {...listeners}
      onClick={onClick}
      onKeyDown={handleKeyDown}
      aria-label={`Appointment: ${booking.client.first_name}${booking.client.last_name ? ` ${booking.client.last_name}` : ''} at ${startTime}. Press space to pick up, arrow keys to move, space to drop, or enter to open.`}
    >
      {/* Service color bar — fallback to stone tint when service.color is null */}
      <span
        className="chair-event-service-bar"
        style={{
          backgroundColor:
            booking.service?.color ??
            'color-mix(in oklch, var(--color-stone) 40%, transparent)',
        }}
        aria-hidden="true"
      />

      <div className="space-y-1">
        {/* Client name + time */}
        <div className="flex items-center justify-between gap-1">
          <span
            className={cn(
              'text-[11px] font-medium truncate',
              isCancelled && 'line-through opacity-60'
            )}
          >
            {booking.client.first_name} {booking.client.last_name ?? ''}
          </span>
          <span className="text-[10px] tabular-nums shrink-0 opacity-70 whitespace-nowrap">{startTime}</span>
        </div>

        {/* Service name */}
        {booking.service?.name && (
          <span className="block text-[10px] opacity-60 truncate">
            {booking.service.name}
          </span>
        )}

        {/* Status pill + session meta */}
        <div className="flex items-center gap-1">
          {statusPill && (
            <span className={cn('status-pill-' + statusPill.toLowerCase())}>
              {statusPill}
            </span>
          )}
          {statusPill === 'HOLD' && booking.deposit_deadline_override && (
            <span className="text-[8px] text-stone tabular-nums">
              {formatDeadlineCountdown(booking.deposit_deadline_override)}
            </span>
          )}
          {booking.session_number != null && (
            <span className="font-serif italic text-[8px] opacity-70 ml-auto">
              S{booking.session_number}
            </span>
          )}
        </div>

        {/* Deposit dot */}
        {(booking.deposit_cents ?? 0) > 0 && (
          <span
            role="img"
            title={booking.deposit_paid ? 'Deposit paid' : 'Deposit pending'}
            aria-label={booking.deposit_paid ? 'Deposit paid' : 'Deposit pending'}
            className={cn('deposit-dot', booking.deposit_paid ? 'paid' : 'unpaid')}
          />
        )}
      </div>

      {/* Resize handle */}
      <div
        className="absolute bottom-0 inset-x-0 h-1.5 cursor-ns-resize hover:bg-rust hover:opacity-30 transition-colors"
        onPointerDown={onResizeStart}
      />
    </div>
  )
}

