import { createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { slugify } from '@/lib/utils'

const ListServicesSchema = z.object({
  is_public: z
    .string()
    .transform((v) => v === 'true')
    .optional(),
})

export async function GET(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  const { searchParams } = new URL(request.url)
  const parsed = ListServicesSchema.safeParse(Object.fromEntries(searchParams))
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })
  }

  try {
    const supabase = await createClient()
    let query = supabase
      .from('services')
      .select(
        'id, name, slug, description, duration_min, base_price_cents, deposit_cents, deposit_required, requires_consultation, is_public, sort_order, color, category, buffer_before_min, buffer_after_min'
      )
      .eq('studio_id', authUser.studioId)
      .order('sort_order', { ascending: true })

    if (parsed.data.is_public !== undefined) {
      query = query.eq('is_public', parsed.data.is_public)
    }

    const { data, error } = await query

    if (error) {
      logger.error({ err: error, studioId: authUser.studioId }, 'services list failed')
      return NextResponse.json({ error: 'Failed to fetch services' }, { status: 500 })
    }

    return NextResponse.json({ data: data ?? [] })
  } catch (err) {
    logger.error({ err }, 'services GET unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

