interface StatusHistoryEntry {
  from: BookingStatus
  to: BookingStatus
  at: string
  by: string
}

interface AppointmentDetailDrawerData {
  id: string
  booking_token: string
  scheduled_at: string
  end_at: string
  duration_min: number
  status: BookingStatus
  price_cents: number
  deposit_cents: number
  deposit_paid: boolean
  deposit_deadline_override: string | null
  status_history: StatusHistoryEntry[] | null
  notes: string | null
  created_at: string
  client: {
    id: string
    first_name: string
    last_name: string | null
    email: string | null
    total_sessions: number
    total_spent_cents: number
  } | null
  artist: {
    id: string
    display_name: string
    avatar_url: string | null
  } | null
  service: {
    id: string
    name: string
    color: string | null
    duration_min: number
  } | null
}

type StudioRole = Database['public']['Tables']['studio_members']['Row']['role']

interface AppointmentDetailDrawerProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  /** Booking ID to fetch. When undefined, drawer shows nothing. */
  appointmentId: string | undefined
  /** Current user role — controls visibility of admin actions. */
  userRole?: StudioRole
}

// ─── Preset deadline extension options ──────────────────────────────────────
const EXTEND_PRESETS = [
  { label: '+12 hours', hours: 12 },
  { label: '+24 hours', hours: 24 },
  { label: '+48 hours', hours: 48 },
] as const

function DrawerSkeleton() {
  return (
    <div className="p-6 space-y-4">
      <div className="flex items-center gap-3">
        <Skeleton className="h-9 w-9 rounded-full" />
        <Skeleton className="h-5 w-40" />
      </div>
      <Skeleton className="h-32 w-full rounded-xl" />
      <Skeleton className="h-24 w-full rounded-xl" />
      <Skeleton className="h-20 w-full rounded-xl" />
    </div>
  )
}

export function AppointmentDetailDrawer({
  open,
  onOpenChange,
  appointmentId,
  userRole,
}: AppointmentDetailDrawerProps) {
  const router = useRouter()
  const queryClient = useQueryClient()
  const [extendDialogOpen, setExtendDialogOpen] = useState(false)
  const [extending, setExtending] = useState(false)
  const [customHours, setCustomHours] = useState<string>('')

  const canExtendDeadline = userRole === 'owner' || userRole === 'admin'

  async function handleExtendDeadline(hours: number) {
    if (!appointmentId) return
    setExtending(true)
    try {
      const res = await fetch(`/api/bookings/${appointmentId}/extend-deadline`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ hours }),
      })
      const body = await res.json() as { ok?: boolean; error?: string; deadline?: string }
      if (!res.ok) throw new Error(body.error ?? 'Failed to extend deadline')

    toast.success(`Deadline extended by ${hours} hours`)
    setExtendDialogOpen(false)
    setCustomHours('')
    // Invalidate so drawer data refreshes
    await queryClient.invalidateQueries({ queryKey: ['booking', appointmentId] })
  } catch (err: unknown) {
    toast.error(err instanceof Error ? err.message : 'Failed to extend deadline')
  } finally {
    setExtending(false)
  }
}

function handleCustomExtend() {
  const h = parseInt(customHours, 10)
  if (Number.isNaN(h) || h < 1) {
    toast.error('Enter a valid number of hours (minimum 1)')
    return
  }
  void handleExtendDeadline(h)
}

const { data, isLoading } = useQuery<{ data: AppointmentDetailDrawerData }>({
  queryKey: ['booking', appointmentId],
  queryFn: async () => {
    const res = await fetch(`/api/bookings/${appointmentId}`)
    if (!res.ok) throw new Error('Booking not found')
    return res.json() as Promise<{ data: AppointmentDetailDrawerData }>
  },
  enabled: open && !!appointmentId,
  staleTime: 30_000,
})

const booking = data?.data

const copyToken = () => {
  if (!booking) return
  void navigator.clipboard.writeText(booking.booking_token.split('-')[0]?.toUpperCase() ?? booking.booking_token)
  toast.success('Reference copied')
}

return (
  <>
  <Sheet open={open} onOpenChange={onOpenChange}>
    <SheetContent
      side="right"
      className="w-full sm:max-w-[480px] flex flex-col overflow-hidden p-0"
    >
      <SheetHeader className="px-6 pt-6 pb-4 border-b border-border/40">
        {isLoading || !booking ? (
          <>
            <Skeleton className="h-5 w-40" />
            <Skeleton className="h-4 w-24 mt-1" />
          </>
        ) : (
          <>
            <div className="flex items-center justify-between gap-2">
              <SheetTitle className="text-base font-semibold">
                {booking.client
                  ? `${booking.client.first_name} ${booking.client.last_name ?? ''}`.trim()
                  : 'Appointment'}
              </SheetTitle>
              <AppointmentStatusBadge status={booking.status} />
            </div>
            <SheetDescription className="sr-only">
              Appointment quick-view for {booking.client?.first_name ?? 'client'}
            </SheetDescription>
            <div className="flex items-center gap-2 mt-1">
              <span className="text-xs text-muted-foreground font-mono">
                #{(booking.booking_token.split('-')[0] ?? booking.booking_token).toUpperCase()}
              </span>
              <button
                type="button"
                onClick={copyToken}
                className="h-4 w-4 text-muted-foreground hover:text-foreground"
                aria-label="Copy booking reference"
              >
                <Copy className="h-3.5 w-3.5" />
              </button>
            </div>
          </>
        )}
      </SheetHeader>

      <div className="flex-1 overflow-y-auto px-6 py-4 space-y-4">
        {isLoading ? (
          <DrawerSkeleton />
        ) : !booking ? (
          <p className="text-sm text-muted-foreground text-center py-8">
            Select an appointment to view details
          </p>
        ) : (
          <>
            {/* At-a-glance card */}
            <div className="rounded-xl border border-border/60 p-4 space-y-3">
              <p className="text-xs font-medium text-muted-foreground uppercase tracking-wide">
                Appointment
              </p>

              <div className="space-y-2 text-sm">
                <div className="flex items-start gap-2">
                  <Calendar className="h-3.5 w-3.5 text-muted-foreground mt-0.5 shrink-0" />
                  <span>
                    {new Date(booking.scheduled_at).toLocaleDateString('en-US', {
                      weekday: 'long',
                      month: 'long',
                      day: 'numeric',
                      year: 'numeric',
                    })}
                  </span>
                </div>
                <div className="flex items-start gap-2">
                  <Clock className="h-3.5 w-3.5 text-muted-foreground mt-0.5 shrink-0" />
                  <span className="tabular-nums">
                    {new Date(booking.scheduled_at).toLocaleTimeString('en-US', {
                      hour: '2-digit',
                      minute: '2-digit',
                    })}
                    {' – '}
                    {new Date(booking.end_at).toLocaleTimeString('en-US', {
                      hour: '2-digit',
                      minute: '2-digit',
                    })}
                    <span className="text-muted-foreground ml-1">· {booking.duration_min} min</span>
                  </span>
                </div>
                {booking.service && (
                  <div className="flex items-start gap-2">
                    <Palette className="h-3.5 w-3.5 text-muted-foreground mt-0.5 shrink-0" />
                    <div className="flex items-center gap-1.5">
                      {booking.service.color && (
                        <span
                          className="h-2 w-2 rounded-full shrink-0"
                          style={{ backgroundColor: booking.service.color }}
                        />
                      )}
                      <span>{booking.service.name}</span>
                    </div>
                  </div>
                )}
                {booking.artist && (
                  <div className="flex items-start gap-2">
                    <User className="h-3.5 w-3.5 text-muted-foreground mt-0.5 shrink-0" />
                    <span>{booking.artist.display_name}</span>
                  </div>
                )}
              </div>

              <div className="pt-3 border-t border-border/40 flex items-center justify-between">
                <div>
                  <p className="text-xs text-muted-foreground">Total</p>
                  <p className="text-base font-semibold tabular-nums">
                    {formatCurrency(booking.price_cents)}
                  </p>
                </div>
                {booking.deposit_cents > 0 && (
                  <DepositStatusBadge
                    depositPaid={booking.deposit_paid}
                    depositCents={booking.deposit_cents}
                  />
                )}
              </div>
            </div>

            {/* Client mini-card */}
            {booking.client && (
              <div className="rounded-xl border border-border/60 p-4 space-y-2">
                <p className="text-xs font-medium text-muted-foreground uppercase tracking-wide">
                  Client
                </p>
                <div className="flex items-center gap-2">
                  <div className="h-8 w-8 rounded-full bg-primary/10 flex items-center justify-center shrink-0">
                    <span className="text-xs font-semibold text-primary">
                      {booking.client.first_name[0]}
                      {booking.client.last_name?.[0] ?? ''}
                    </span>
                  </div>
                  <div className="min-w-0">
                    <p className="text-sm font-medium truncate">
                      {booking.client.first_name} {booking.client.last_name ?? ''}

