async function handleCancel() {
  if (!appointmentId) return
  setCancelling(true)
  try {
    const res = await fetch(`/api/bookings/${appointmentId}`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ status: 'cancelled' }),
    })
    if (!res.ok) {
      const body = await res.json() as { error?: string }
      throw new Error(body.error ?? 'Cancellation failed')
    }
    toast.success('Appointment cancelled')
    setCancelDialogOpen(false)
    await queryClient.invalidateQueries({ queryKey: ['booking', appointmentId] })
    await queryClient.invalidateQueries({ queryKey: ['bookings'] })
    onOpenChange(false)
  } catch (err) {
    logger.error({ err, bookingId: appointmentId }, 'booking cancel failed')
    toast.error(err instanceof Error ? err.message : 'Failed to cancel appointment')
  } finally {
    setCancelling(false)
  }
}

