import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser } from '@/lib/supabase/server'
import { createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { checkFeatureRpc } from '@/lib/billing/feature-gate'
import { enqueueJob } from '@/lib/queue'
import { smsTemplates } from '@/lib/sms/templates'
import type { Database } from '@/lib/supabase/types'

type BookingUpdate = Database['public']['Tables']['bookings']['Update']

const UpdateBookingSchema = z.object({
  artist_id: z.string().uuid().optional(),
  service_id: z.string().uuid().nullable().optional(),
  location_id: z.string().uuid().nullable().optional(),
  scheduled_at: z.string().datetime().optional(),
  duration_min: z.number().int().min(15).max(480).optional(),
  price_cents: z.number().int().min(0).optional(),
  deposit_cents: z.number().int().min(0).optional(),
  notes: z.string().max(2000).nullable().optional(),
  client_notes: z.string().max(2000).nullable().optional(),
  // When true, skip side-effect notifications (SMS, emails). Used for undo flows
  // so we don't double-SMS a client when they undo within 6s.
  suppress_notifications: z.boolean().optional(),
})

interface Params {
  params: Promise<{ id: string }>
}

export async function GET(_request: NextRequest, { params }: Params) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  const { id } = await params
  if (!z.string().uuid().safeParse(id).success) {
    return NextResponse.json({ error: 'Invalid booking ID' }, { status: 400 })
  }

  try {
    const supabase = await createClient()
    const { data, error } = await supabase
      .from('bookings')
      .select(
        `
        *,
        client:clients(id, first_name, last_name, email, phone, total_sessions, total_spent_cents, tags, notes),
        artist:artists(id, display_name, avatar_url, sort_order),
        service:services(id, name, duration_min, base_price_cents, deposit_cents, color),
        location:locations(id, name, address, city),
        photos:booking_photos(id, kind, caption, taken_at, storage_path)
      `
      )
      .eq('id', id)
      .eq('studio_id', authUser.studioId)
      .single()

    if (error || !data) {
      return NextResponse.json({ error: 'Booking not found' }, { status: 404 })
    }

    return NextResponse.json({ data })
  } catch (err) {
    logger.error({ err, bookingId: id }, 'booking GET unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

export async function PATCH(request: NextRequest, { params }: Params) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  const { id } = await params
  if (!z.string().uuid().safeParse(id).success) {
    return NextResponse.json({ error: 'Invalid booking ID' }, { status: 400 })
  }

  let body: unknown
  try {
    body = await request.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = UpdateBookingSchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })
  }

  if (Object.keys(parsed.data).length === 0) {
    return NextResponse.json({ error: 'No fields to update' }, { status: 400 })
  }

  try {
    const supabase = await createClient()

    // Capture original scheduled_at + artist_id to detect reschedule
    const { data: originalBooking } = await supabase
      .from('bookings')
      .select('scheduled_at, artist_id, client_id')
      .eq('id', id)
      .eq('studio_id', authUser.studioId)
      .single()

    // Pull suppress_notifications out — control flag, not a DB column
    const { suppress_notifications, ...dbFields } = parsed.data

    // Strip undefined values — required for exactOptionalPropertyTypes + Supabase update
    const updates = Object.fromEntries(
      Object.entries(dbFields).filter(([, v]) => v !== undefined)
    ) as BookingUpdate

    if (Object.keys(updates).length === 0) {
      return NextResponse.json({ error: 'No fields to update' }, { status: 400 })
    }
    const { data, error } = await supabase
      .from('bookings')
      .update(updates)
      .eq('id', id)
      .eq('studio_id', authUser.studioId)
      .select('id, scheduled_at, end_at, duration_min, status, price_cents, notes, updated_at')
      .single()

    if (error) {
      if (error.code === '23P01') {
        return NextResponse.json(
          { error: 'That time slot is already booked for this artist' },
          { status: 409 }
        )
      }
      if (error.code === 'PGRST116') {
        return NextResponse.json({ error: 'Booking not found' }, { status: 404 })
      }
      logger.error({ err: error, bookingId: id }, 'booking PATCH failed')
      return NextResponse.json({ error: 'Failed to update booking' }, { status: 500 })
    }

    // Fire reschedule SMS if time or artist changed (non-blocking)
    if (originalBooking && data && !suppress_notifications) {
      const scheduledChanged =
        originalBooking.scheduled_at !== data.scheduled_at
      const artistChanged =
        parsed.data.artist_id !== undefined &&
        parsed.data.artist_id !== originalBooking.artist_id
      if (scheduledChanged || artistChanged) {
        void dispatchRescheduleSms({
          supabase,
          bookingId: id,
          studioId: authUser.studioId,
          newScheduledAt: data.scheduled_at,
        }).catch((err) => {
          logger.error({ err, bookingId: id }, 'reschedule SMS dispatch failed')
        })
      }
    }

    return NextResponse.json({ data })
  } catch (err) {
    logger.error({ err, bookingId: id }, 'booking PATCH unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

// Non-blocking SMS dispatch — errors logged, never thrown to caller
async function dispatchRescheduleSms(params: {
  supabase: Awaited<ReturnType<typeof createClient>>
  bookingId: string
  studioId: string
  newScheduledAt: string
}): Promise<void> {
  const { supabase, bookingId, studioId, newScheduledAt } = params

  const hasFeature = await checkFeatureRpc(supabase, studioId, 'sms_reminders')
  if (!hasFeature) return

  const { data: ctx } = await supabase
    .from('bookings')
    .select(`
      id,
      client:clients(id, first_name, phone),
      artist:artists(display_name),
      service:services(name),
      studio:studios(name)
    `)
    .eq('id', bookingId)
    .eq('studio_id', studioId)
    .single()

  if (!ctx || !ctx.client?.phone || !ctx.client?.id) return

  const body = smsTemplates.rescheduled({
    clientFirstName: ctx.client.first_name ?? 'there',
    studioName: ctx.studio?.name ?? 'your studio',
    serviceName: ctx.service?.name ?? 'tattoo appointment',
    artistName: ctx.artist?.display_name ?? 'your artist',
    newScheduledAt: new Date(newScheduledAt),
  })

  const { data: comm, error: commErr } = await supabase
    .from('client_communications')
    .insert({
      studio_id: studioId,
      client_id: ctx.client.id,
      booking_id: bookingId,
      channel: 'sms',
      direction: 'outbound',
      status: 'queued',
      body,
    })
    .select('id')
    .single()

  if (commErr || !comm) {
    logger.error(
      { err: commErr, bookingId },
      'reschedule SMS: failed to insert client_communications row'
    )
    return
  }

  await enqueueJob('send-sms', { commId: comm.id, studioId })
}

export async function DELETE(_request: NextRequest, { params }: Params) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  const { id } = await params
  if (!z.string().uuid().safeParse(id).success) {
    return NextResponse.json({ error: 'Invalid booking ID' }, { status: 400 })
  }

  try {
    const supabase = await createClient()
    const { error } = await supabase
      .from('bookings')
      .update({ status: 'cancelled', cancelled_at: new Date().toISOString() })
      .eq('id', id)
      .eq('studio_id', authUser.studioId)

    if (error) {
      if (error.code === 'PGRST116') {
        return NextResponse.json({ error: 'Booking not found' }, { status: 404 })
      }
      logger.error({ err: error, bookingId: id }, 'booking DELETE failed')
      return NextResponse.json({ error: 'Failed to cancel booking' }, { status: 500 })
    }

    return new NextResponse(null, { status: 204 })
  } catch (err) {
    logger.error({ err, bookingId: id }, 'booking DELETE unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

