'use client'

/**
 * BookingLinkQR — renders a scannable QR code of the studio's public
 * booking URL. Used in empty-state calendar surfaces (DB-empty + day-empty)
 * so a studio can hold up an iPad to a client and have them book themselves.
 *
 * Hidden on mobile (<640px) — small screens scan QR codes they display badly,
 * and the copy-link fallback is always available next to this component.
 */

import { useEffect, useState } from 'react'
import { useQuery } from '@tanstack/react-query'
import QRCode from 'qrcode'
import { Skeleton } from '@/components/ui/skeleton'
import { cn } from '@/lib/utils'
import { logger } from '@/lib/logger'

interface BookingLinksResponse {
  data: {
    studioUrl: string
    studioSlug: string
  }
}

interface BookingLinkQRProps {
  /** Optional size override. Default 128px. */
  size?: number
  /** Hide on mobile breakpoints. Default true. */
  hideOnMobile?: boolean
  className?: string
}

export function BookingLinkQR({
  size = 128,
  hideOnMobile = true,
  className,
}: BookingLinkQRProps) {
  const [dataUrl, setDataUrl] = useState<string | null>(null)
  const [error, setError] = useState<string | null>(null)

  const { data, isLoading } = useQuery<BookingLinksResponse>({
    queryKey: ['booking-links'],
    queryFn: async () => {
      const res = await fetch('/api/booking-links')
      if (!res.ok) throw new Error('Failed to fetch booking link')
      return res.json() as Promise<BookingLinksResponse>
    },
    staleTime: 10 * 60_000,
  })

  const studioUrl = data?.data.studioUrl

  useEffect(() => {
    if (!studioUrl) {
      setDataUrl(null)
      return
    }
    let cancelled = false
    QRCode.toDataURL(studioUrl, {
      width: size * 2, // render 2x for retina sharpness
      margin: 1,
      color: {
        dark: '#0F0F0F', // Onyx
        light: '#F7F7F5', // Bone
      },
    })
      .then((url) => {
        if (!cancelled) setDataUrl(url)
      })
      .catch((err: unknown) => {
        logger.error({ err }, 'booking-link QR generation failed')
        if (!cancelled) setError('QR unavailable')
      })
    return () => {
      cancelled = true
    }
  }, [studioUrl, size])

  if (error) return null

  return (
    <div
      className={cn(
        'shrink-0 rounded-md border border-border bg-bone p-1.5',
        hideOnMobile && 'hidden sm:block',
        className
      )}
      style={{ width: size + 12, height: size + 12 }}
      aria-label="Booking link QR code"
    >
      {isLoading || !dataUrl ? (
        <Skeleton className="w-full h-full rounded" />
      ) : (
        <img
          src={dataUrl}
          alt={studioUrl ? `QR code for ${studioUrl}` : 'Studio booking link QR code'}
          width={size}
          height={size}
          className="block w-full h-full"
        />
      )}
    </div>
  )
}

