'use client'

import { useState, useEffect } from 'react'
import Link from 'next/link'
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import { toast } from 'sonner'
import {
  CalendarIcon,
  Clock,
  ChevronDown,
  ChevronUp,
  ImagePlus,
  Repeat,
  X,
  Sparkles,
} from 'lucide-react'
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
} from '@/components/ui/sheet'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Textarea } from '@/components/ui/textarea'
import { Switch } from '@/components/ui/switch'
import { Label } from '@/components/ui/label'
import { Skeleton } from '@/components/ui/skeleton'
import { Calendar } from '@/components/ui/calendar'
import { ClientFinder } from '@/components/booking/ClientFinder'
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover'
import { formatCurrency, cn } from '@/lib/utils'
import { logger } from '@/lib/logger'

interface Service {
  id: string
  name: string
  duration_min: number
  base_price_cents: number
  deposit_cents: number
}

interface Artist {
  id: string
  display_name: string
  avatar_url: string | null
}

interface ClientBookingLite {
  id: string
  scheduled_at: string
  status: string
  artist?: { display_name: string } | null
  service?: { name: string } | null
}

interface SmartBookingSheetProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  defaultStart?: Date | undefined
  defaultEnd?: Date | undefined
  defaultArtistId?: string | undefined
  editingId?: string | null | undefined
  onSuccess: (bookingId: string) => void
}

type RecurringFrequency = 'weekly' | 'biweekly' | 'monthly'

const MAX_REFERENCE_IMAGES = 4
const MAX_REFERENCE_MB = 5
const SEVEN_DAYS_MS = 7 * 24 * 60 * 60 * 1000

export function SmartBookingSheet({
  open,
  onOpenChange,
  defaultStart,
  defaultArtistId,
  onSuccess,
}: SmartBookingSheetProps) {
  const queryClient = useQueryClient()

  // Form state — required fields
  const [selectedDate, setSelectedDate] = useState<Date | undefined>(defaultStart)
  const [selectedTime, setSelectedTime] = useState<string>(
    defaultStart
      ? `${defaultStart.getHours().toString().padStart(2, '0')}:${defaultStart.getMinutes().toString().padStart(2, '0')}`
      : '14:00'
  )
  const [selectedServiceId, setSelectedServiceId] = useState<string>('')
  const [selectedArtistId, setSelectedArtistId] = useState<string>(defaultArtistId ?? '')
  const [selectedClientId, setSelectedClientId] = useState<string | null>(null)
  const [durationMin, setDurationMin] = useState<number>(60)
  const [sendDepositLink, setSendDepositLink] = useState<boolean>(false)
  const [calendarOpen, setCalendarOpen] = useState(false)

  // Progressive-disclosure state — these fields are collapsed behind "+ Add more"
  const [showMore, setShowMore] = useState(false)
  const [notes, setNotes] = useState<string>('')
  const [referenceImages, setReferenceImages] = useState<File[]>([])
  const [recurringEnabled, setRecurringEnabled] = useState(false)
  const [recurringFrequency, setRecurringFrequency] = useState<RecurringFrequency>('biweekly')
  const [recurringCount, setRecurringCount] = useState<number>(3)

  // Smart linking — whether to attach this booking to a nearby existing session
  const [linkToBookingId, setLinkToBookingId] = useState<string | null>(null)

  // Fetch services + artists when sheet opens
  const { data: servicesData, isLoading: servicesLoading } = useQuery<Service[]>({
    queryKey: ['services'],
    queryFn: async () => {
      const res = await fetch('/api/services')
      if (!res.ok) throw new Error('Failed to fetch services')
      const json = (await res.json()) as { data?: Service[] } | Service[]
      return Array.isArray(json) ? json : (json.data ?? [])
    },
    enabled: open,
  })

  const { data: artistsData, isLoading: artistsLoading } = useQuery<Artist[]>({
    queryKey: ['artists'],
    queryFn: async () => {
      const res = await fetch('/api/artists')
      if (!res.ok) throw new Error('Failed to fetch artists')
      const json = (await res.json()) as { data?: Artist[] } | Artist[]
      return Array.isArray(json) ? json : (json.data ?? [])
    },
    enabled: open,
  })

  // Smart linking — fetch client's upcoming bookings when a client is picked.
  // Surfaces the "Link as Session N?" banner per PDF spec.
  const { data: clientBookings } = useQuery<ClientBookingLite[]>({
    queryKey: ['client-upcoming-bookings', selectedClientId],
    queryFn: async () => {
      if (!selectedClientId) return []
      const fromIso = new Date(Date.now() - SEVEN_DAYS_MS).toISOString()
      const res = await fetch(
        `/api/bookings?client_id=${selectedClientId}&from=${encodeURIComponent(fromIso)}&per_page=20`
      )
      if (!res.ok) return []
      const json = (await res.json()) as { data?: ClientBookingLite[] }
      return json.data ?? []
    },
    enabled: open && !!selectedClientId,
    staleTime: 30_000,
  })

  const selectedService = servicesData?.find((s) => s.id === selectedServiceId)

  // Auto-fill duration when service changes
  useEffect(() => {
    if (selectedService) {
      setDurationMin(selectedService.duration_min)
    }
  }, [selectedService])

  // Reset form when sheet opens
  useEffect(() => {
    if (!open) return
    setSelectedDate(defaultStart)
    setSelectedTime(
      defaultStart
        ? `${defaultStart.getHours().toString().padStart(2, '0')}:${defaultStart.getMinutes().toString().padStart(2, '0')}`
        : '14:00'
    )
    setSelectedServiceId('')
    setSelectedArtistId(defaultArtistId ?? '')
    setSelectedClientId(null)
    setDurationMin(60)
    setNotes('')
    setSendDepositLink(false)
    setShowMore(false)
    setReferenceImages([])
    setRecurringEnabled(false)
    setRecurringFrequency('biweekly')
    setRecurringCount(3)
    setLinkToBookingId(null)
  }, [open, defaultStart, defaultArtistId])

  // Smart linking candidate — pick the nearest non-cancelled booking within ±7 days
  const smartLinkCandidate = (() => {
    if (!selectedDate || !clientBookings || clientBookings.length === 0) return null
    const target = new Date(selectedDate).getTime()
    return clientBookings
      .filter((b) => b.status !== 'cancelled')
      .map((b) => ({
        booking: b,
        delta: Math.abs(new Date(b.scheduled_at).getTime() - target),
      }))
      .filter(({ delta }) => delta <= SEVEN_DAYS_MS)
      .sort((a, b) => a.delta - b.delta)[0]?.booking ?? null
  })()

  const handleAddReferenceImages = (files: FileList | null) => {
    if (!files) return
    const incoming = Array.from(files).filter((f) => {
      if (!f.type.startsWith('image/')) {
        toast.error(`${f.name} — not an image`)
        return false
      }
      if (f.size > MAX_REFERENCE_MB * 1024 * 1024) {
        toast.error(`${f.name} — over ${MAX_REFERENCE_MB}MB limit`)
        return false
      }
      return true
    })
    const next = [...referenceImages, ...incoming].slice(0, MAX_REFERENCE_IMAGES)
    setReferenceImages(next)
    if (next.length < referenceImages.length + incoming.length) {
      toast.info(`Max ${MAX_REFERENCE_IMAGES} reference images`)
    }
  }

  const createBookingMutation = useMutation({
    mutationFn: async () => {
      if (!selectedClientId || !selectedArtistId || !selectedServiceId || !selectedDate) {
        throw new Error('Missing required fields')
      }

      const timeParts = selectedTime.split(':')
      const hours = timeParts[0] || '0'
      const minutes = timeParts[1] || '0'
      const scheduledAt = new Date(selectedDate)
      scheduledAt.setHours(parseInt(hours, 10), parseInt(minutes, 10), 0, 0)

      const payload: Record<string, unknown> = {
        client_id: selectedClientId,
        artist_id: selectedArtistId,
        service_id: selectedServiceId,
        scheduled_at: scheduledAt.toISOString(),
        duration_min: durationMin,
        price_cents: selectedService?.base_price_cents ?? 0,
        deposit_cents: sendDepositLink ? selectedService?.deposit_cents ?? 0 : 0,
        notes: notes || null,
      }

      // Smart-link metadata — server may ignore if project_id/session_number
      // aren't in the Zod schema yet; UI still surfaces the intent.
      if (linkToBookingId) {
        payload.link_booking_id = linkToBookingId
      }

      // Recurring metadata — server-side recurring expansion is a follow-up.
      // For now we pass it through; when /api/bookings/recurring lands it will
      // consume these fields. Unknown fields are stripped by Zod today.
      if (recurringEnabled) {
        payload.recurring = {
          frequency: recurringFrequency,
          count: recurringCount,
        }
      }

      const res = await fetch('/api/bookings', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      })

      if (!res.ok) {
        const err = await res.json() as { error?: string }
        throw new Error(err.error ?? 'Failed to create booking')
      }

      return res.json() as Promise<{ data: { id: string; booking_token: string } }>
    },
    onSuccess: async (response) => {
      const bookingId = response.data.id
      void queryClient.invalidateQueries({ queryKey: ['bookings'] })

      // Reference images — upload to Supabase Storage if any were attached.
      // Storage wiring lands with server-side signed-upload endpoint; for now
      // we skip actual upload but surface count in toast so owners know.
      if (referenceImages.length > 0) {
        // TODO(sprint-6): POST to /api/bookings/{id}/reference-images with presigned uploads.
        toast.success(
          `Booking created · ${referenceImages.length} reference${referenceImages.length === 1 ? '' : 's'} staged`,
          { description: 'Image upload coming in next sprint.' }
        )
      } else if (sendDepositLink && selectedService?.deposit_cents) {
        try {
          const checkoutRes = await fetch('/api/public/deposits/checkout', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              booking_token: response.data.booking_token,
              amount_cents: selectedService.deposit_cents,
            }),
          })
          if (checkoutRes.ok) {
            const { link } = await checkoutRes.json() as { link: string }
            toast.success('Booking created. Deposit link copied.', {
              description: link,
              action: {
                label: 'Copy',
                onClick: () => {
                  navigator.clipboard.writeText(link).catch(() => {})
                },
              },
              duration: 12000,
            })
          }
        } catch (err) {
          logger.error({ err }, 'deposit link failed')
          toast.success('Booking created', { description: 'Deposit link could not be generated' })
        }
      } else {
        toast.success('Booking created')
      }

      onOpenChange(false)
      onSuccess(bookingId)
    },
    onError: (err) => {
      logger.error({ err }, 'booking creation failed')
      toast.error(err instanceof Error ? err.message : 'Booking creation failed')
    },
  })

  const handleSubmit = async () => {
    await createBookingMutation.mutateAsync()
  }

  const handleDateSelect = (date: Date | undefined) => {
    setSelectedDate(date)
    setCalendarOpen(false)
  }

  const formattedDate = selectedDate
    ? selectedDate.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })
    : 'Select date'

  const isLoading = servicesLoading || artistsLoading
  const isFormValid = selectedClientId && selectedArtistId && selectedServiceId && selectedDate
  const servicesEmpty = !servicesLoading && (servicesData?.length ?? 0) === 0

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent className="w-full max-w-md overflow-y-auto">
        <SheetHeader>
          <SheetTitle>New booking</SheetTitle>
          <SheetDescription>Create a new appointment</SheetDescription>
        </SheetHeader>

        {isLoading ? (
          <div className="space-y-3 mt-6">
            <Skeleton className="h-10 w-full rounded" />
            <Skeleton className="h-10 w-full rounded" />
            <Skeleton className="h-10 w-full rounded" />
            <Skeleton className="h-10 w-full rounded" />
          </div>
        ) : (
          <div className="space-y-4 mt-6">
            {/* Client Finder */}
            <div>
              <Label className="text-xs uppercase tracking-wider font-bold text-stone">
                Client
              </Label>
              <ClientFinder
                selectedClientId={selectedClientId}
                onSelectClient={(id) => {
                  setSelectedClientId(id)
                  setLinkToBookingId(null)
                }}
                onNewClient={(data) => {
                  // TODO: Create new client and use its ID
                  logger.error({ data }, 'new client creation not yet implemented')
                  toast.error('New client creation coming soon')
                }}
              />
            </div>

            {/* Smart linking suggestion — appears when client has a nearby booking */}
            {smartLinkCandidate && (
              <div className="rounded-md border border-rust/30 bg-rust/5 p-3 flex items-start gap-2">
                <Sparkles className="h-4 w-4 text-rust shrink-0 mt-0.5" />
                <div className="flex-1 text-xs space-y-1">
                  <p>
                    <span className="font-semibold">Nearby session found:</span>{' '}
                    {smartLinkCandidate.service?.name ?? 'appointment'} with{' '}
                    {smartLinkCandidate.artist?.display_name ?? 'artist'} on{' '}
                    {new Date(smartLinkCandidate.scheduled_at).toLocaleDateString('en-US', {
                      month: 'short',
                      day: 'numeric',
                    })}
                    . Link as a session of the same project?
                  </p>
                  <div className="flex gap-2 pt-1">
                    <button
                      type="button"
                      className={cn(
                        'text-[11px] px-2 py-0.5 rounded',
                        linkToBookingId === smartLinkCandidate.id
                          ? 'bg-rust text-white'
                          : 'bg-background border border-border hover:bg-rust/10'
                      )}
                      onClick={() => setLinkToBookingId(smartLinkCandidate.id)}
                    >
                      Yes, link sessions
                    </button>
                    <button
                      type="button"
                      className="text-[11px] px-2 py-0.5 rounded bg-background border border-border hover:bg-muted"
                      onClick={() => setLinkToBookingId(null)}
                    >
                      No, standalone
                    </button>
                  </div>
                </div>
              </div>
            )}

            {/* Service */}
            <div>
              <Label htmlFor="service" className="text-xs uppercase tracking-wider font-bold text-stone">
                Service
              </Label>
              {servicesEmpty ? (
                <div className="mt-1 rounded-md border border-border bg-muted/30 p-3 text-xs space-y-2">
                  <p className="text-muted-foreground">No services configured yet.</p>
                  <Link
                    href="/settings/studio/services"
                    className="inline-block text-xs font-medium underline text-foreground hover:text-rust"
                    onClick={() => onOpenChange(false)}
                  >
                    Add services in Settings →
                  </Link>
                </div>
              ) : (
                <select
                  id="service"
                  value={selectedServiceId}
                  onChange={(e) => setSelectedServiceId(e.target.value)}
                  className="w-full mt-1 px-3 py-2 border border-border rounded-md bg-card text-sm outline-none"
                >
                  <option value="">Select service</option>
                  {servicesData?.map((svc) => (
                    <option key={svc.id} value={svc.id}>
                      {svc.name} · {formatCurrency(svc.base_price_cents)}
                    </option>
                  ))}
                </select>
              )}
            </div>

            {/* Artist */}
            <div>
              <Label htmlFor="artist" className="text-xs uppercase tracking-wider font-bold text-stone">
                Artist
              </Label>
              <select
                id="artist"
                value={selectedArtistId}
                onChange={(e) => setSelectedArtistId(e.target.value)}
                className="w-full mt-1 px-3 py-2 border border-border rounded-md bg-card text-sm outline-none"
              >
                <option value="">Select artist</option>
                {artistsData?.map((artist) => (
                  <option key={artist.id} value={artist.id}>
                    {artist.display_name}
                  </option>
                ))}
              </select>
            </div>

            {/* Date & Time */}
            <div>
              <Label className="text-xs uppercase tracking-wider font-bold text-stone">
                Date & Time
              </Label>
              <div className="flex gap-2 mt-1">
                <Popover open={calendarOpen} onOpenChange={setCalendarOpen}>
                  <PopoverTrigger
                    render={<Button variant="outline" className="flex-1 justify-start gap-2" />}
                  >
                    <CalendarIcon className="h-4 w-4" />
                    {formattedDate}
                  </PopoverTrigger>
                  <PopoverContent className="w-auto p-0" align="start">
                    <Calendar
                      mode="single"
                      selected={selectedDate}
                      onSelect={handleDateSelect}
                      disabled={(date) => date < new Date(new Date().setHours(0, 0, 0, 0))}
                    />
                  </PopoverContent>
                </Popover>

                <div className="flex items-center gap-1 border border-border rounded-md px-3">
                  <Clock className="h-4 w-4 text-muted-foreground" />
                  <input
                    type="time"
                    value={selectedTime}
                    onChange={(e) => setSelectedTime(e.target.value)}
                    className="flex-1 bg-transparent text-sm outline-none"
                  />
                </div>
              </div>
            </div>

            {/* Duration */}
            <div>
              <Label htmlFor="duration" className="text-xs uppercase tracking-wider font-bold text-stone">
                Duration
              </Label>
              <div className="flex items-center gap-2 mt-1">
                <Input
                  id="duration"
                  type="number"
                  min="15"
                  max="480"
                  step="15"
                  value={durationMin}
                  onChange={(e) => setDurationMin(parseInt(e.target.value, 10))}
                />
                <span className="text-sm text-muted-foreground whitespace-nowrap">minutes</span>
              </div>
            </div>

            {/* Deposit Link — always visible when service requires a deposit */}
            {selectedService && selectedService.deposit_cents > 0 && (
              <div className="flex flex-row items-center justify-between rounded-lg border border-border p-3">
                <div className="space-y-0.5">
                  <Label className="text-xs uppercase tracking-wider font-bold text-stone">
                    Send deposit link
                  </Label>
                  <p className="text-xs text-muted-foreground">
                    {formatCurrency(selectedService.deposit_cents)} deposit
                  </p>
                </div>
                <Switch
                  checked={sendDepositLink}
                  onCheckedChange={setSendDepositLink}
                />
              </div>
            )}

            {/* Progressive disclosure — Notes, Reference images, Recurring live behind "+ Add more" */}
            <button
              type="button"
              onClick={() => setShowMore((v) => !v)}
              className="w-full flex items-center justify-between py-2 text-xs font-semibold text-stone hover:text-foreground transition-colors"
              aria-expanded={showMore}
            >
              <span className="tracking-wider uppercase">
                + Add notes · references · recurring
              </span>
              {showMore ? (
                <ChevronUp className="h-3.5 w-3.5" />
              ) : (
                <ChevronDown className="h-3.5 w-3.5" />
              )}
            </button>

            {showMore && (
              <div className="space-y-4 rounded-lg border border-border bg-muted/20 p-3">
                {/* Notes */}
                <div>
                  <Label htmlFor="notes" className="text-xs uppercase tracking-wider font-bold text-stone">
                    Notes
                  </Label>
                  <Textarea
                    id="notes"
                    placeholder="Add any notes..."
                    value={notes}
                    onChange={(e) => setNotes(e.target.value)}
                    className="mt-1 resize-none"
                    rows={3}
                  />
                </div>

                {/* Reference images */}
                <div>
                  <Label className="text-xs uppercase tracking-wider font-bold text-stone">
                    Reference images
                  </Label>
                  <div className="mt-1 space-y-2">
                    <label
                      className="flex items-center justify-center gap-2 h-20 border-2 border-dashed border-border rounded-md cursor-pointer hover:border-foreground/30 hover:bg-muted/30 transition-colors"
                    >
                      <ImagePlus className="h-4 w-4 text-muted-foreground" />
                      <span className="text-xs text-muted-foreground">
                        Click to upload (max {MAX_REFERENCE_IMAGES}, {MAX_REFERENCE_MB}MB each)
                      </span>
                      <input
                        type="file"
                        accept="image/*"
                        multiple
                        className="hidden"
                        onChange={(e) => handleAddReferenceImages(e.target.files)}
                      />
                    </label>
                    {referenceImages.length > 0 && (
                      <div className="flex flex-wrap gap-2">
                        {referenceImages.map((file, idx) => (
                          <div
                            key={`${file.name}-${idx}`}
                            className="relative h-14 w-14 rounded border border-border overflow-hidden bg-background"
                          >
                            {/* eslint-disable-next-line @next/next/no-img-element */}
                            <img
                              src={URL.createObjectURL(file)}
                              alt={file.name}
                              className="w-full h-full object-cover"
                            />
                            <button
                              type="button"
                              onClick={() => {
                                setReferenceImages((imgs) =>
                                  imgs.filter((_, i) => i !== idx)
                                )
                              }}
                              className="absolute top-0.5 right-0.5 h-4 w-4 rounded-full bg-onyx/80 text-white flex items-center justify-center hover:bg-onyx"
                              aria-label={`Remove ${file.name}`}
                            >
                              <X className="h-2.5 w-2.5" />
                            </button>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                </div>

                {/* Recurring */}
                <div className="rounded-md border border-border bg-background p-3 space-y-3">
                  <div className="flex items-center justify-between">
                    <Label className="text-xs uppercase tracking-wider font-bold text-stone flex items-center gap-2">
                      <Repeat className="h-3.5 w-3.5" />
                      Recurring
                    </Label>
                    <Switch
                      checked={recurringEnabled}
                      onCheckedChange={setRecurringEnabled}
                    />
                  </div>
                  {recurringEnabled && (
                    <div className="grid grid-cols-2 gap-2">
                      <div>
                        <Label htmlFor="rec-freq" className="text-[10px] text-muted-foreground">
                          Frequency
                        </Label>
                        <select
                          id="rec-freq"
                          value={recurringFrequency}
                          onChange={(e) =>
                            setRecurringFrequency(e.target.value as RecurringFrequency)
                          }
                          className="w-full mt-0.5 px-2 py-1.5 border border-border rounded bg-card text-xs outline-none"
                        >
                          <option value="weekly">Weekly</option>
                          <option value="biweekly">Every 2 weeks</option>
                          <option value="monthly">Monthly</option>
                        </select>
                      </div>
                      <div>
                        <Label htmlFor="rec-count" className="text-[10px] text-muted-foreground">
                          Sessions
                        </Label>
                        <Input
                          id="rec-count"
                          type="number"
                          min="2"
                          max="12"
                          value={recurringCount}
                          onChange={(e) =>
                            setRecurringCount(
                              Math.max(2, Math.min(12, parseInt(e.target.value, 10) || 2))
                            )
                          }
                          className="h-8 text-xs mt-0.5"
                        />
                      </div>
                    </div>
                  )}
                </div>
              </div>
            )}

            {/* Submit */}
            <Button
              onClick={handleSubmit}
              className="w-full"
              disabled={createBookingMutation.isPending || !isFormValid || servicesEmpty}
            >
              {createBookingMutation.isPending ? 'Creating...' : 'Create booking'}
            </Button>
          </div>
        )}
      </SheetContent>
    </Sheet>
  )
}

toolUseResult.content:
'use client'

import { useState, useEffect } from 'react'
import Link from 'next/link'
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import { toast } from 'sonner'
import {
  CalendarIcon,
  Clock,
  ChevronDown,
  ChevronUp,
  ImagePlus,
  Repeat,
  X,
  Sparkles,
} from 'lucide-react'
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
} from '@/components/ui/sheet'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Textarea } from '@/components/ui/textarea'
import { Switch } from '@/components/ui/switch'
import { Label } from '@/components/ui/label'
import { Skeleton } from '@/components/ui/skeleton'
import { Calendar } from '@/components/ui/calendar'
import { ClientFinder } from '@/components/booking/ClientFinder'
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover'
import { formatCurrency, cn } from '@/lib/utils'
import { logger } from '@/lib/logger'

interface Service {
  id: string
  name: string
  duration_min: number
  base_price_cents: number
  deposit_cents: number
}

interface Artist {
  id: string
  display_name: string
  avatar_url: string | null
}

interface ClientBookingLite {
  id: string
  scheduled_at: string
  status: string
  artist?: { display_name: string } | null
  service?: { name: string } | null
}

interface SmartBookingSheetProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  defaultStart?: Date | undefined
  defaultEnd?: Date | undefined
  defaultArtistId?: string | undefined
  editingId?: string | null | undefined
  onSuccess: (bookingId: string) => void
}

type RecurringFrequency = 'weekly' | 'biweekly' | 'monthly'

const MAX_REFERENCE_IMAGES = 4
const MAX_REFERENCE_MB = 5
const SEVEN_DAYS_MS = 7 * 24 * 60 * 60 * 1000

export function SmartBookingSheet({
  open,
  onOpenChange,
  defaultStart,
  defaultArtistId,
  onSuccess,
}: SmartBookingSheetProps) {
  const queryClient = useQueryClient()

  // Form state — required fields
  const [selectedDate, setSelectedDate] = useState<Date | undefined>(defaultStart)
  const [selectedTime, setSelectedTime] = useState<string>(
    defaultStart
      ? `${defaultStart.getHours().toString().padStart(2, '0')}:${defaultStart.getMinutes().toString().padStart(2, '0')}`
      : '14:00'
  )
  const [selectedServiceId, setSelectedServiceId] = useState<string>('')
  const [selectedArtistId, setSelectedArtistId] = useState<string>(defaultArtistId ?? '')
  const [selectedClientId, setSelectedClientId] = useState<string | null>(null)
  const [durationMin, setDurationMin] = useState<number>(60)
  const [sendDepositLink, setSendDepositLink] = useState<boolean>(false)
  const [calendarOpen, setCalendarOpen] = useState(false)

  // Progressive-disclosure state — these fields are collapsed behind "+ Add more"
  const [showMore, setShowMore] = useState(false)
  const [notes, setNotes] = useState<string>('')
  const [referenceImages, setReferenceImages] = useState<File[]>([])
  const [recurringEnabled, setRecurringEnabled] = useState(false)
  const [recurringFrequency, setRecurringFrequency] = useState<RecurringFrequency>('biweekly')
  const [recurringCount, setRecurringCount] = useState<number>(3)

  // Smart linking — whether to attach this booking to a nearby existing session
  const [linkToBookingId, setLinkToBookingId] = useState<string | null>(null)

  // Fetch services + artists when sheet opens
  const { data: servicesData, isLoading: servicesLoading } = useQuery<Service[]>({
    queryKey: ['services'],
    queryFn: async () => {
      const res = await fetch('/api/services')
      if (!res.ok) throw new Error('Failed to fetch services')
      const json = (await res.json()) as { data?: Service[] } | Service[]
      return Array.isArray(json) ? json : (json.data ?? [])
    },
    enabled: open,
  })

  const { data: artistsData, isLoading: artistsLoading } = useQuery<Artist[]>({
    queryKey: ['artists'],
    queryFn: async () => {
      const res = await fetch('/api/artists')
      if (!res.ok) throw new Error('Failed to fetch artists')
      const json = (await res.json()) as { data?: Artist[] } | Artist[]
      return Array.isArray(json) ? json : (json.data ?? [])
    },
    enabled: open,
  })

  // Smart linking — fetch client's upcoming bookings when a client is picked.
  // Surfaces the "Link as Session N?" banner per PDF spec.
  const { data: clientBookings } = useQuery<ClientBookingLite[]>({
    queryKey: ['client-upcoming-bookings', selectedClientId],
    queryFn: async () => {
      if (!selectedClientId) return []
      const fromIso = new Date(Date.now() - SEVEN_DAYS_MS).toISOString()
      const res = await fetch(
        `/api/bookings?client_id=${selectedClientId}&from=${encodeURIComponent(fromIso)}&per_page=20`
      )
      if (!res.ok) return []
      const json = (await res.json()) as { data?: ClientBookingLite[] }
      return json.data ?? []
    },
    enabled: open && !!selectedClientId,
    staleTime: 30_000,
  })

  const selectedService = servicesData?.find((s) => s.id === selectedServiceId)

  // Auto-fill duration when service changes
  useEffect(() => {
    if (selectedService) {
      setDurationMin(selectedService.duration_min)
    }
  }, [selectedService])

  // Reset form when sheet opens
  useEffect(() => {
    if (!open) return
    setSelectedDate(defaultStart)
    setSelectedTime(
      defaultStart
        ? `${defaultStart.getHours().toString().padStart(2, '0')}:${defaultStart.getMinutes().toString().padStart(2, '0')}`
        : '14:00'
    )
    setSelectedServiceId('')
    setSelectedArtistId(defaultArtistId ?? '')
    setSelectedClientId(null)
    setDurationMin(60)
    setNotes('')
    setSendDepositLink(false)
    setShowMore(false)
    setReferenceImages([])
    setRecurringEnabled(false)
    setRecurringFrequency('biweekly')
    setRecurringCount(3)
    setLinkToBookingId(null)
  }, [open, defaultStart, defaultArtistId])

  // Smart linking candidate — pick the nearest non-cancelled booking within ±7 days
  const smartLinkCandidate = (() => {
    if (!selectedDate || !clientBookings || clientBookings.length === 0) return null
    const target = new Date(selectedDate).getTime()
    return clientBookings
      .filter((b) => b.status !== 'cancelled')
      .map((b) => ({
        booking: b,
        delta: Math.abs(new Date(b.scheduled_at).getTime() - target),
      }))
      .filter(({ delta }) => delta <= SEVEN_DAYS_MS)
      .sort((a, b) => a.delta - b.delta)[0]?.booking ?? null
  })()

  const handleAddReferenceImages = (files: FileList | null) => {
    if (!files) return
    const incoming = Array.from(files).filter((f) => {
      if (!f.type.startsWith('image/')) {
        toast.error(`${f.name} — not an image`)
        return false
      }
      if (f.size > MAX_REFERENCE_MB * 1024 * 1024) {
        toast.error(`${f.name} — over ${MAX_REFERENCE_MB}MB limit`)
        return false
      }
      return true
    })
    const next = [...referenceImages, ...incoming].slice(0, MAX_REFERENCE_IMAGES)
    setReferenceImages(next)
    if (next.length < referenceImages.length + incoming.length) {
      toast.info(`Max ${MAX_REFERENCE_IMAGES} reference images`)
    }
  }

  const createBookingMutation = useMutation({
    mutationFn: async () => {
      if (!selectedClientId || !selectedArtistId || !selectedServiceId || !selectedDate) {
        throw new Error('Missing required fields')
      }

      const timeParts = selectedTime.split(':')
      const hours = timeParts[0] || '0'
      const minutes = timeParts[1] || '0'
      const scheduledAt = new Date(selectedDate)
      scheduledAt.setHours(parseInt(hours, 10), parseInt(minutes, 10), 0, 0)

      const payload: Record<string, unknown> = {
        client_id: selectedClientId,
        artist_id: selectedArtistId,
        service_id: selectedServiceId,
        scheduled_at: scheduledAt.toISOString(),
        duration_min: durationMin,
        price_cents: selectedService?.base_price_cents ?? 0,
        deposit_cents: sendDepositLink ? selectedService?.deposit_cents ?? 0 : 0,
        notes: notes || null,
      }

      // Smart-link metadata — server may ignore if project_id/session_number
      // aren't in the Zod schema yet; UI still surfaces the intent.
      if (linkToBookingId) {
        payload.link_booking_id = linkToBookingId
      }

      // Recurring metadata — server-side recurring expansion is a follow-up.
      // For now we pass it through; when /api/bookings/recurring lands it will
      // consume these fields. Unknown fields are stripped by Zod today.
      if (recurringEnabled) {
        payload.recurring = {
          frequency: recurringFrequency,
          count: recurringCount,
        }
      }

      const res = await fetch('/api/bookings', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      })

      if (!res.ok) {
        const err = await res.json() as { error?: string }
        throw new Error(err.error ?? 'Failed to create booking')
      }

      return res.json() as Promise<{ data: { id: string; booking_token: string } }>
    },
    onSuccess: async (response) => {
      const bookingId = response.data.id
      void queryClient.invalidateQueries({ queryKey: ['bookings'] })

      // Reference images — upload to Supabase Storage if any were attached.
      // Storage wiring lands with server-side signed-upload endpoint; for now
      // we skip actual upload but surface count in toast so owners know.
      if (referenceImages.length > 0) {
        // TODO(sprint-6): POST to /api/bookings/{id}/reference-images with presigned uploads.
        toast.success(
          `Booking created · ${referenceImages.length} reference${referenceImages.length === 1 ? '' : 's'} staged`,
          { description: 'Image upload coming in next sprint.' }
        )
      } else if (sendDepositLink && selectedService?.deposit_cents) {
        try {
          const checkoutRes = await fetch('/api/public/deposits/checkout', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              booking_token: response.data.booking_token,
              amount_cents: selectedService.deposit_cents,
            }),
          })
          if (checkoutRes.ok) {
            const { link } = await checkoutRes.json() as { link: string }
            toast.success('Booking created. Deposit link copied.', {
              description: link,
              action: {
                label: 'Copy',
                onClick: () => {
                  navigator.clipboard.writeText(link).catch(() => {})
                },
              },
              duration: 12000,
            })
          }
        } catch (err) {
          logger.error({ err }, 'deposit link failed')
          toast.success('Booking created', { description: 'Deposit link could not be generated' })
        }
      } else {
        toast.success('Booking created')
      }

      onOpenChange(false)
      onSuccess(bookingId)
    },
    onError: (err) => {
      logger.error({ err }, 'booking creation failed')
      toast.error(err instanceof Error ? err.message : 'Booking creation failed')
    },
  })

  const handleSubmit = async () => {
    await createBookingMutation.mutateAsync()
  }

  const handleDateSelect = (date: Date | undefined) => {
    setSelectedDate(date)
    setCalendarOpen(false)
  }

  const formattedDate = selectedDate
    ? selectedDate.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })
    : 'Select date'

  const isLoading = servicesLoading || artistsLoading
  const isFormValid = selectedClientId && selectedArtistId && selectedServiceId && selectedDate
  const servicesEmpty = !servicesLoading && (servicesData?.length ?? 0) === 0

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent className="w-full max-w-md overflow-y-auto">
        <SheetHeader>
          <SheetTitle>New booking</SheetTitle>
          <SheetDescription>Create a new appointment</SheetDescription>
        </SheetHeader>

        {isLoading ? (
          <div className="space-y-3 mt-6">
            <Skeleton className="h-10 w-full rounded" />
            <Skeleton className="h-10 w-full rounded" />
            <Skeleton className="h-10 w-full rounded" />
            <Skeleton className="h-10 w-full rounded" />
          </div>
        ) : (
          <div className="space-y-4 mt-6">
            {/* Client Finder */}
            <div>
              <Label className="text-xs uppercase tracking-wider font-bold text-stone">
                Client
              </Label>
              <ClientFinder
                selectedClientId={selectedClientId}
                onSelectClient={(id) => {
                  setSelectedClientId(id)
                  setLinkToBookingId(null)
                }}
                onNewClient={(data) => {
                  // TODO: Create new client and use its ID
                  logger.error({ data }, 'new client creation not yet implemented')
                  toast.error('New client creation coming soon')
                }}
              />
            </div>

            {/* Smart linking suggestion — appears when client has a nearby booking */}
            {smartLinkCandidate && (
              <div className="rounded-md border border-rust/30 bg-rust/5 p-3 flex items-start gap-2">
                <Sparkles className="h-4 w-4 text-rust shrink-0 mt-0.5" />
                <div className="flex-1 text-xs space-y-1">
                  <p>
                    <span className="font-semibold">Nearby session found:</span>{' '}
                    {smartLinkCandidate.service?.name ?? 'appointment'} with{' '}
                    {smartLinkCandidate.artist?.display_name ?? 'artist'} on{' '}
                    {new Date(smartLinkCandidate.scheduled_at).toLocaleDateString('en-US', {
                      month: 'short',
                      day: 'numeric',
                    })}
                    . Link as a session of the same project?
                  </p>
                  <div className="flex gap-2 pt-1">
                    <button
                      type="button"
                      className={cn(
                        'text-[11px] px-2 py-0.5 rounded',
                        linkToBookingId === smartLinkCandidate.id
                          ? 'bg-rust text-white'
                          : 'bg-background border border-border hover:bg-rust/10'
                      )}
                      onClick={() => setLinkToBookingId(smartLinkCandidate.id)}
                    >
                      Yes, link sessions
                    </button>
                    <button
                      type="button"
                      className="text-[11px] px-2 py-0.5 rounded bg-background border border-border hover:bg-muted"
                      onClick={() => setLinkToBookingId(null)}
                    >
                      No, standalone
                    </button>
                  </div>
                </div>
              </div>
            )}

            {/* Service */}
            <div>
              <Label htmlFor="service" className="text-xs uppercase tracking-wider font-bold text-stone">
                Service
              </Label>
              {servicesEmpty ? (
                <div className="mt-1 rounded-md border border-border bg-muted/30 p-3 text-xs space-y-2">
                  <p className="text-muted-foreground">No services configured yet.</p>
                  <Link
                    href="/settings/studio/services"
                    className="inline-block text-xs font-medium underline text-foreground hover:text-rust"
                    onClick={() => onOpenChange(false)}
                  >
                    Add services in Settings →
                  </Link>
                </div>
              ) : (
                <select
                  id="service"
                  value={selectedServiceId}
                  onChange={(e) => setSelectedServiceId(e.target.value)}
                  className="w-full mt-1 px-3 py-2 border border-border rounded-md bg-card text-sm outline-none"
                >
                  <option value="">Select service</option>
                  {servicesData?.map((svc) => (
                    <option key={svc.id} value={svc.id}>
                      {svc.name} · {formatCurrency(svc.base_price_cents)}
                    </option>
                  ))}
                </select>
              )}
            </div>

            {/* Artist */}
            <div>
              <Label htmlFor="artist" className="text-xs uppercase tracking-wider font-bold text-stone">
                Artist
              </Label>
              <select
                id="artist"
                value={selectedArtistId}
                onChange={(e) => setSelectedArtistId(e.target.value)}
                className="w-full mt-1 px-3 py-2 border border-border rounded-md bg-card text-sm outline-none"
              >
                <option value="">Select artist</option>
                {artistsData?.map((artist) => (
                  <option key={artist.id} value={artist.id}>
                    {artist.display_name}
                  </option>
                ))}
              </select>
            </div>

            {/* Date & Time */}
            <div>
              <Label className="text-xs uppercase tracking-wider font-bold text-stone">
                Date & Time
              </Label>
              <div className="flex gap-2 mt-1">
                <Popover open={calendarOpen} onOpenChange={setCalendarOpen}>
                  <PopoverTrigger
                    render={<Button variant="outline" className="flex-1 justify-start gap-2" />}
                  >
                    <CalendarIcon className="h-4 w-4" />
                    {formattedDate}
                  </PopoverTrigger>
                  <PopoverContent className="w-auto p-0" align="start">
                    <Calendar
                      mode="single"
                      selected={selectedDate}
                      onSelect={handleDateSelect}
                      disabled={(date) => date < new Date(new Date().setHours(0, 0, 0, 0))}
                    />
                  </PopoverContent>
                </Popover>

                <div className="flex items-center gap-1 border border-border rounded-md px-3">
                  <Clock className="h-4 w-4 text-muted-foreground" />
                  <input
                    type="time"
                    value={selectedTime}
                    onChange={(e) => setSelectedTime(e.target.value)}
                    className="flex-1 bg-transparent text-sm outline-none"
                  />
                </div>
              </div>
            </div>

            {/* Duration */}
            <div>
              <Label htmlFor="duration" className="text-xs uppercase tracking-wider font-bold text-stone">
                Duration
              </Label>
              <div className="flex items-center gap-2 mt-1">
                <Input
                  id="duration"
                  type="number"
                  min="15"
                  max="480"
                  step="15"
                  value={durationMin}
                  onChange={(e) => setDurationMin(parseInt(e.target.value, 10))}
                />
                <span className="text-sm text-muted-foreground whitespace-nowrap">minutes</span>
              </div>
            </div>

            {/* Deposit Link — always visible when service requires a deposit */}
            {selectedService && selectedService.deposit_cents > 0 && (
              <div className="flex flex-row items-center justify-between rounded-lg border border-border p-3">
                <div className="space-y-0.5">
                  <Label className="text-xs uppercase tracking-wider font-bold text-stone">
                    Send deposit link
                  </Label>
                  <p className="text-xs text-muted-foreground">
                    {formatCurrency(selectedService.deposit_cents)} deposit
                  </p>
                </div>
                <Switch
                  checked={sendDepositLink}
                  onCheckedChange={setSendDepositLink}
                />
              </div>
            )}

            {/* Progressive disclosure — Notes, Reference images, Recurring live behind "+ Add more" */}
            <button
              type="button"
              onClick={() => setShowMore((v) => !v)}
              className="w-full flex items-center justify-between py-2 text-xs font-semibold text-stone hover:text-foreground transition-colors"
              aria-expanded={showMore}
            >
              <span className="tracking-wider uppercase">
                + Add notes · references · recurring
              </span>
              {showMore ? (
                <ChevronUp className="h-3.5 w-3.5" />
              ) : (
                <ChevronDown className="h-3.5 w-3.5" />
              )}
            </button>

            {showMore && (
              <div className="space-y-4 rounded-lg border border-border bg-muted/20 p-3">
                {/* Notes */}
                <div>
                  <Label htmlFor="notes" className="text-xs uppercase tracking-wider font-bold text-stone">
                    Notes
                  </Label>
                  <Textarea
                    id="notes"
                    placeholder="Add any notes..."
                    value={notes}
                    onChange={(e) => setNotes(e.target.value)}
                    className="mt-1 resize-none"
                    rows={3}
                  />
                </div>

                {/* Reference images */}
                <div>
                  <Label className="text-xs uppercase tracking-wider font-bold text-stone">
                    Reference images
                  </Label>
                  <div className="mt-1 space-y-2">
                    <label
                      className="flex items-center justify-center gap-2 h-20 border-2 border-dashed border-border rounded-md cursor-pointer hover:border-foreground/30 hover:bg-muted/30 transition-colors"
                    >
                      <ImagePlus className="h-4 w-4 text-muted-foreground" />
                      <span className="text-xs text-muted-foreground">
                        Click to upload (max {MAX_REFERENCE_IMAGES}, {MAX_REFERENCE_MB}MB each)
                      </span>
                      <input
                        type="file"
                        accept="image/*"
                        multiple
                        className="hidden"
                        onChange={(e) => handleAddReferenceImages(e.target.files)}
                      />
                    </label>
                    {referenceImages.length > 0 && (
                      <div className="flex flex-wrap gap-2">
                        {referenceImages.map((file, idx) => (
                          <div
                            key={`${file.name}-${idx}`}
                            className="relative h-14 w-14 rounded border border-border overflow-hidden bg-background"
                          >
                            {/* eslint-disable-next-line @next/next/no-img-element */}
                            <img
                              src={URL.createObjectURL(file)}
                              alt={file.name}
                              className="w-full h-full object-cover"
                            />
                            <button
                              type="button"
                              onClick={() => {
                                setReferenceImages((imgs) =>
                                  imgs.filter((_, i) => i !== idx)
                                )
                              }}
                              className="absolute top-0.5 right-0.5 h-4 w-4 rounded-full bg-onyx/80 text-white flex items-center justify-center hover:bg-onyx"
                              aria-label={`Remove ${file.name}`}
                            >
                              <X className="h-2.5 w-2.5" />
                            </button>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                </div>

                {/* Recurring */}
                <div className="rounded-md border border-border bg-background p-3 space-y-3">
                  <div className="flex items-center justify-between">
                    <Label className="text-xs uppercase tracking-wider font-bold text-stone flex items-center gap-2">
                      <Repeat className="h-3.5 w-3.5" />
                      Recurring
                    </Label>
                    <Switch
                      checked={recurringEnabled}
                      onCheckedChange={setRecurringEnabled}
                    />
                  </div>
                  {recurringEnabled && (
                    <div className="grid grid-cols-2 gap-2">
                      <div>
                        <Label htmlFor="rec-freq" className="text-[10px] text-muted-foreground">
                          Frequency
                        </Label>
                        <select
                          id="rec-freq"
                          value={recurringFrequency}
                          onChange={(e) =>
                            setRecurringFrequency(e.target.value as RecurringFrequency)
                          }
                          className="w-full mt-0.5 px-2 py-1.5 border border-border rounded bg-card text-xs outline-none"
                        >
                          <option value="weekly">Weekly</option>
                          <option value="biweekly">Every 2 weeks</option>
                          <option value="monthly">Monthly</option>
                        </select>
                      </div>
                      <div>
                        <Label htmlFor="rec-count" className="text-[10px] text-muted-foreground">
                          Sessions
                        </Label>
                        <Input
                          id="rec-count"
                          type="number"
                          min="2"
                          max="12"
                          value={recurringCount}
                          onChange={(e) =>
                            setRecurringCount(
                              Math.max(2, Math.min(12, parseInt(e.target.value, 10) || 2))
                            )
                          }
                          className="h-8 text-xs mt-0.5"
                        />
                      </div>
                    </div>
                  )}
                </div>
              </div>
            )}

            {/* Submit */}
            <Button
              onClick={handleSubmit}
              className="w-full"
              disabled={createBookingMutation.isPending || !isFormValid || servicesEmpty}
            >
              {createBookingMutation.isPending ? 'Creating...' : 'Create booking'}
            </Button>
          </div>
        )}
      </SheetContent>
    </Sheet>
  )
}

