input.content:
-- Calendar Demo Seed
-- Populates studio 35012312-c749-4d46-9063-57786f2705cf with PDF-mockup data:
--   4 artists, 6 services (each with category), 1 demo client, 1 multi-session project,
--   10 bookings spread across today (LIVE / PAID / HOLD mix), 1 blocked time slot.
-- Idempotent via ON CONFLICT / NOT EXISTS guards. Safe to re-run.

DO $$
DECLARE
  v_studio_id uuid := '35012312-c749-4d46-9063-57786f2705cf';
  v_artist_kaia uuid;
  v_artist_miles uuid;
  v_artist_sasha uuid;
  v_artist_guest uuid;
  v_service_neotrad uuid;
  v_service_fineline uuid;
  v_service_bg uuid;
  v_service_color uuid;
  v_service_script uuid;
  v_service_touchup uuid;
  v_client uuid;
  v_project uuid;
  v_today_8am timestamptz;
BEGIN
  v_today_8am := date_trunc('day', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' + interval '8 hours';

  -- ─── Artists (idempotent by display_name + studio_id) ────────────────────
  SELECT id INTO v_artist_kaia FROM artists WHERE studio_id=v_studio_id AND display_name='Kaia Okafor' LIMIT 1;
  IF v_artist_kaia IS NULL THEN
    INSERT INTO artists (studio_id, display_name, specialties, sort_order, status)
    VALUES (v_studio_id, 'Kaia Okafor', ARRAY['Neo-traditional'], 1, 'active')
    RETURNING id INTO v_artist_kaia;
  END IF;

  SELECT id INTO v_artist_miles FROM artists WHERE studio_id=v_studio_id AND display_name='Miles Vance' LIMIT 1;
  IF v_artist_miles IS NULL THEN
    INSERT INTO artists (studio_id, display_name, specialties, sort_order, status)
    VALUES (v_studio_id, 'Miles Vance', ARRAY['Fine-line', 'Script'], 2, 'active')
    RETURNING id INTO v_artist_miles;
  END IF;

  SELECT id INTO v_artist_sasha FROM artists WHERE studio_id=v_studio_id AND display_name='Sasha Reyes' LIMIT 1;
  IF v_artist_sasha IS NULL THEN
    INSERT INTO artists (studio_id, display_name, specialties, sort_order, status)
    VALUES (v_studio_id, 'Sasha Reyes', ARRAY['Black & grey'], 3, 'active')
    RETURNING id INTO v_artist_sasha;
  END IF;

  SELECT id INTO v_artist_guest FROM artists WHERE studio_id=v_studio_id AND display_name='Guest · Riley' LIMIT 1;
  IF v_artist_guest IS NULL THEN
    INSERT INTO artists (studio_id, display_name, specialties, sort_order, status)
    VALUES (v_studio_id, 'Guest · Riley', ARRAY['Color'], 4, 'active')
    RETURNING id INTO v_artist_guest;
  END IF;

  -- ─── Services (idempotent by slug + studio_id) ──────────────────────────
  SELECT id INTO v_service_neotrad FROM services WHERE studio_id=v_studio_id AND slug='neo-traditional-sleeve' LIMIT 1;
  IF v_service_neotrad IS NULL THEN
    INSERT INTO services (studio_id, name, slug, duration_min, base_price_cents, deposit_cents, category, sort_order, is_public)
    VALUES (v_studio_id, 'Neo-traditional sleeve', 'neo-traditional-sleeve', 120, 34000, 10000, 'neo_traditional', 1, true)
    RETURNING id INTO v_service_neotrad;
