// Sync view to FullCalendar on change — deferred to microtask so FullCalendar's
// internal flushSync runs AFTER React's commit phase completes. Calling
// changeView() synchronously inside useEffect triggers a "flushSync was called
// from inside a lifecycle method" warning in React 19 + Next.js 16.
useEffect(() => {
  const api = calendarRef.current?.getApi()
  if (!api) return
  const id = queueMicrotask(() => {
    // Re-fetch the api in case the ref changed during the microtask wait
    const current = calendarRef.current?.getApi()
    if (!current) return
    current.changeView(view)
  })
  try {
    localStorage.setItem('inkos-calendar-view', view)
  } catch {
    // localStorage unavailable (private mode, quota) — ignore
  }
  return () => {
    // queueMicrotask has no cancel primitive; the view check above handles stale refs
    void id
  }
}, [view])

