#!/usr/bin/env node
/* eslint-disable no-console */

/**
 * InkOS migration runner — idempotent, deploy-safe, non-fatal on error.
 *
 * Runs on every Railway boot BEFORE the Next.js server starts. Reads every
 * *.sql file in supabase/migrations/, tracks which have been applied in the
 * `_inkos_migrations` table, and applies any new ones in timestamp order
 * inside a single transaction per file.
 *
 * Failure mode: logs the error + continues to the next migration. NEVER
 * fails the deploy — the server still boots. This is intentional: a broken
 * migration should not take the whole site offline. Operator investigates
 * via logs and either fixes the SQL or rolls back manually.
 *
 * Environment:
 *   SUPABASE_DB_URL              Direct Postgres connection string (required
 *                                for prod). Get from Supabase Dashboard →
 *                                Settings → Database → Connection string →
 *                                "Direct connection" (not pooler).
 *                                Format: postgresql://postgres:PASSWORD@
 *                                db.PROJECT.supabase.co:5432/postgres
 *   INKOS_MIGRATIONS_DISABLED    Set to "1" to skip entirely (useful for
 *                                preview envs that share a DB).
 *
 * Behavior when SUPABASE_DB_URL is missing:
 *   Log a warning, exit 0. App still boots. Migrations stay un-applied.
 *   This makes the script safe to land before the env var is configured.
 */

import { readFileSync, readdirSync } from 'node:fs'
import { resolve, join, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'
import postgres from 'postgres'

const __dirname = dirname(fileURLToPath(import.meta.url))
const MIGRATIONS_DIR = resolve(__dirname, '..', 'supabase', 'migrations')
const DB_URL = process.env.SUPABASE_DB_URL ?? process.env.DATABASE_URL

// Emergency kill-switch
if (process.env.INKOS_MIGRATIONS_DISABLED === '1') {
  console.log('[migrations] INKOS_MIGRATIONS_DISABLED=1 — skipping')
  process.exit(0)
}

if (!DB_URL) {
  console.warn(
    '[migrations] SUPABASE_DB_URL not set — skipping auto-apply. ' +
      'Set it in Railway env vars to enable. Boot continues.',
  )
  process.exit(0)
}

// Redact password in logs
function redactDbUrl(url) {
  return url.replace(/\/\/([^:]+):[^@]+@/, '//$1:***@')
}

async function main() {
  console.log(`[migrations] Connecting to ${redactDbUrl(DB_URL)}`)

  const sql = postgres(DB_URL, {
    max: 1,
    idle_timeout: 10,
    connect_timeout: 15,
    ssl: 'require',
    // Silence noisy notices; we only care about errors
    onnotice: () => {},
  })

  try {
    // Bootstrap the tracking table. Safe to re-run.
    await sql`
      create table if not exists public._inkos_migrations (
        filename text primary key,
        applied_at timestamptz not null default now(),
        sha256 text
      )
    `
    console.log('[migrations] Tracking table ready')

    // Fetch already-applied set
    const applied = await sql`select filename from public._inkos_migrations`
    const appliedSet = new Set(applied.map((r) => r.filename))

    // Enumerate migration files in lexicographic (= timestamp) order
    let files
    try {
      files = readdirSync(MIGRATIONS_DIR)
        .filter((f) => f.endsWith('.sql'))
        .sort()
    } catch (err) {
      console.error(`[migrations] Cannot read ${MIGRATIONS_DIR}: ${err.message}`)
      process.exit(0)
    }

    const pending = files.filter((f) => !appliedSet.has(f))

    if (pending.length === 0) {
      console.log(`[migrations] All ${files.length} migrations up-to-date`)
      return
    }

    console.log(
      `[migrations] Applying ${pending.length} pending migration(s) out of ${files.length} total`,
    )

    let applied_count = 0
    let failed_count = 0

    for (const filename of pending) {
      const filepath = join(MIGRATIONS_DIR, filename)
      let content
      try {
        content = readFileSync(filepath, 'utf-8')
      } catch (err) {
        console.error(`[migrations] ✗ ${filename} — cannot read: ${err.message}`)
        failed_count++
        continue
      }

      try {
        // Each migration in its own transaction. postgres.js auto-wraps in
        // an implicit txn when we use sql.begin().
        await sql.begin(async (tx) => {
          await tx.unsafe(content)
          await tx`
            insert into public._inkos_migrations (filename)
            values (${filename})
            on conflict (filename) do nothing
          `
        })
        console.log(`[migrations] ✓ ${filename}`)
        applied_count++
      } catch (err) {
        console.error(`[migrations] ✗ ${filename} — ${err.message}`)
        if (err.position) console.error(`             position ${err.position}`)
        if (err.where) console.error(`             where ${err.where}`)
        failed_count++
        // Non-fatal: keep going. If a later migration depends on this one
        // it will also fail; operator gets a full picture in logs.
      }
    }

    console.log(
      `[migrations] Done — applied ${applied_count}, failed ${failed_count}, skipped ${
        files.length - pending.length
      }`,
    )
  } finally {
    await sql.end({ timeout: 5 })
  }
}

main().catch((err) => {
  // Last-line-of-defense catch. Log + exit 0 so the deploy still boots.
  console.error('[migrations] Fatal error in runner:', err)
  console.error('[migrations] Continuing boot despite migration failure')
  process.exit(0)
})

