#!/usr/bin/env node
/* eslint-disable no-console */

/**
 * Reload PostgREST schema cache on the remote Supabase DB.
 *
 * When you apply DDL outside the normal migration runner (e.g. a surgical
 * `ALTER TABLE` via Supabase Dashboard SQL Editor, `supabase db query`, or
 * a partial migration), PostgREST's in-memory schema cache stays stale. The
 * app will see "column does not exist" 500 errors on fields that ARE in the
 * database.
 *
 * This script issues `NOTIFY pgrst, 'reload schema'` which triggers PostgREST
 * to re-introspect the schema within a few seconds.
 *
 * Usage:
 *   node scripts/reload-postgrest.mjs
 *
 * Required env:
 *   SUPABASE_DB_URL        Direct Postgres URL (Settings → Database → Direct)
 *     OR
 *   SUPABASE_ACCESS_TOKEN  + run `supabase db query --linked "NOTIFY pgrst, 'reload schema'"` as alternative
 */

import postgres from 'postgres'

const DB_URL = process.env.SUPABASE_DB_URL ?? process.env.DATABASE_URL

if (!DB_URL) {
  console.error('[reload-pgrst] SUPABASE_DB_URL not set')
  console.error('[reload-pgrst] Alternative: run `supabase db query --linked "NOTIFY pgrst, \'reload schema\'"`')
  process.exit(1)
}

const sql = postgres(DB_URL, { max: 1, idle_timeout: 5 })

try {
  await sql`NOTIFY pgrst, 'reload schema'`
  console.log('[reload-pgrst] ✓ Schema reload notified. PostgREST will re-introspect within ~5s.')
} catch (err) {
  console.error(`[reload-pgrst] ✗ ${err.message}`)
  process.exit(1)
} finally {
  await sql.end({ timeout: 5 })
}

