 * GET /api/health/schema
 *
 * Dev-only schema sanity check. Verifies that columns the calendar API relies on
 * exist + that PostgREST can see them. Returns an explicit pass/fail per column
 * so drift is obvious in dev logs without having to grep 500s.
 *
 * Call: `curl http://localhost:3100/api/health/schema`
 *
 * Prod behavior: returns 404 when NODE_ENV === 'production' to keep the surface
 * private. Flip the guard if you need it in staging.
 */
import { NextResponse } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { logger } from '@/lib/logger'

// Columns the calendar feature (and a few other high-traffic routes) rely on.
// Kept surgical — not a replacement for full schema validation, just a canary.
const CRITICAL_COLUMNS: Array<{ table: string; column: string }> = [
  { table: 'bookings', column: 'deposit_deadline_override' },
  { table: 'bookings', column: 'project_id' },
  { table: 'bookings', column: 'session_number' },
  { table: 'bookings', column: 'price_cents' },
  { table: 'bookings', column: 'deposit_paid' },
  { table: 'services', column: 'category' },
  { table: 'services', column: 'color' },
  { table: 'projects', column: 'total_sessions_planned' },
  { table: 'studios', column: 'deposit_deadline_hours' },
  { table: 'artists', column: 'specialties' },
  { table: 'studio_members', column: 'deactivated_at' },
]

export async function GET() {
  if (process.env.NODE_ENV === 'production') {
    return NextResponse.json({ error: 'Not found' }, { status: 404 })
  }

  const supabase = await createClient()
  const results: Array<{ table: string; column: string; ok: boolean; err?: string }> = []

  for (const { table, column } of CRITICAL_COLUMNS) {
    try {
      // Tiny probe — limit 0 + select the column. Postgres returns
      // empty rows but errors on unknown column.
      const { error } = await supabase.from(table).select(column).limit(0)
      if (error) {
        results.push({ table, column, ok: false, err: error.message })
      } else {
        results.push({ table, column, ok: true })
      }
    } catch (err) {
      results.push({
        table,
        column,
        ok: false,
        err: err instanceof Error ? err.message : 'probe failed',
      })
    }
  }

  const missing = results.filter((r) => !r.ok)
  if (missing.length > 0) {
    logger.warn(
      { missing },
      'schema-health: detected stale/missing columns — run `node scripts/reload-postgrest.mjs` or apply the backing migration'
    )
  }

  return NextResponse.json({
    ok: missing.length === 0,
    checked: results.length,
    missing_count: missing.length,
    results,
    hint:
      missing.length > 0
        ? 'run: node scripts/reload-postgrest.mjs OR supabase db query --linked "NOTIFY pgrst, \'reload schema\'"'
        : null,
  })
}

